                                  onChange={(e) => setFormHouse(e.target.value as HouseTeam)}
                              >
                                  <option value="">None</option>
                                  <option value="Palash">Palash</option>
                                  <option value="Amaltash">Amaltash</option>
                                  <option value="Devdar">Devdar</option>
                                  <option value="Gulmohar">Gulmohar</option>
                              </select>
                          </div>
                          <div>
                              <label className="block text-xs text-slate-500 mb-1">Student Post</label>
                              <input className="w-full px-4 py-2 border rounded-lg" value={formPost} onChange={e => setFormPost(e.target.value)} placeholder="e.g Head Boy" />
                          </div>
                      </div>
                    </div>
                  </>
              )}

              <div className="flex gap-3 pt-6 border-t border-slate-100 mt-4">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 border rounded-lg hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { User, StudentRecord, MarkEntry, Announcement, HouseTeam, UserRole } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash, Megaphone, Calendar, Shield, Flag } from 'lucide-react';
import { getStoredStudents, getStoredAnnouncements, getStoredUsers } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  useEffect(() => {
     const allAnn = getStoredAnnouncements();
     const relevantAnn = allAnn.filter(a => a.audience === 'all' || a.audience === 'student');
     setAnnouncements(relevantAnn);
  }, []);

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

   const getHouseColor = (house?: HouseTeam) => {
    switch(house) {
        case 'Palash': return 'text-green-600 bg-green-50 border-green-200';
        case 'Amaltash': return 'text-blue-600 bg-blue-50 border-blue-200';
        case 'Devdar': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
        case 'Gulmohar': return 'text-red-600 bg-red-50 border-red-200';
        default: return 'text-slate-600 bg-slate-50';
    }
  };

  if (currentPage === 'teachers') {
      const studentProfile = getStudentProfile();
      const allUsers = getStoredUsers();

      // Filter teachers. If assignedClass is strict, use it. 
      // If student profile not found or teacher has no class assigned, fallback logic can be applied, 
      // but here we simply show teachers matching the class or all if the system is loose.
      // For this implementation: Show teachers assigned to this student's class.
      const myTeachers = allUsers.filter(u => 
          u.role === UserRole.TEACHER && 
          (u.assignedClass === studentProfile?.className)
      );

      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Teachers</h1>
                 <p className="text-slate-500">Faculty directory for Class {studentProfile?.className || 'N/A'}</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {myTeachers.length === 0 ? (
                      <div className="col-span-full p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                           <UserIcon size={48} className="mx-auto mb-4 opacity-20" />
                           <p>No specific class teachers found.</p>
                      </div>
                  ) : (
                      myTeachers.map(teacher => (
                          <div key={teacher.uid} className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden hover:shadow-md transition-shadow">
                              <div className="p-6 flex flex-col items-center text-center border-b border-slate-50">
                                  <img 
                                      src={teacher.avatarUrl} 
                                      alt={teacher.name} 
                                      className="w-20 h-20 rounded-full bg-slate-100 object-cover mb-4 border-4 border-white shadow-sm"
                                  />
                                  <h3 className="font-bold text-lg text-slate-800">{teacher.name}</h3>
                                  <p className="text-blue-600 font-medium text-sm">{teacher.assignedSubject || 'Teacher'}</p>
                                  <p className="text-slate-400 text-xs mt-1">{teacher.designation}</p>
                              </div>
                              <div className="p-4 bg-slate-50 space-y-3">
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Mail size={16} />
                                      </div>
                                      <div className="overflow-hidden">
                                          <p className="text-xs text-slate-500 font-bold uppercase">Email</p>
                                          <p className="text-slate-700 truncate" title={teacher.email || 'N/A'}>
                                              {teacher.email || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Phone size={16} />
                                      </div>
                                      <div>
                                          <p className="text-xs text-slate-500 font-bold uppercase">Contact</p>
                                          <p className="text-slate-700">
                                              {teacher.contactNumber || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'profile') {
    const studentProfile = getStudentProfile();

    if (!studentProfile) {
        return (
            <div className="p-8 text-center bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="text-slate-400 mb-2">
                    <UserIcon size={48} className="mx-auto opacity-50" />
                </div>
                <h3 className="text-lg font-bold text-slate-700">Profile Not Found</h3>
                <p className="text-slate-500">
                    Detailed information is not available. Please ask your class teacher to update your student record.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
             <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                {/* Header Section */}
                <div className="bg-slate-50 p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 font-mono text-sm">
                            <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-slate-700 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
                            </span>
                            {studentProfile.studentPost && (
                                <span className="px-3 py-1 bg-purple-100 border border-purple-200 rounded-full text-purple-700 flex items-center gap-1 font-semibold">
                                    <Shield size={14} /> {studentProfile.studentPost}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {/* Details Grid */}
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">

                    {/* Academic Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Academic Information</h3>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Class</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.className}</p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Roll Number</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.rollNumber}</p>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">House Team</label>
                                <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(studentProfile.house)}`}>
                                    <Flag size={18} />
                                    {studentProfile.house || 'No House Assigned'}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age & Gender</label>
                                <p className="text-lg font-medium text-slate-800">
                                    {studentProfile.age ? `${studentProfile.age} Years Old` : <span className="text-slate-400 italic">Not set</span>}
                                    <span className="mx-2 text-slate-300">|</span>
                                    {studentProfile.gender || 'Not set'}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Date of Birth</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Calendar size={18} className="text-slate-400" />
                                    {studentProfile.dob ? new Date(studentProfile.dob).toLocaleDateString(undefined, {
                                        year: 'numeric',
                                        month: 'long',
                                        day: 'numeric'
                                    }) : <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-purple-100 text-purple-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Mother's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.motherContact || 'N/A'}</p>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">Latest updates from the school administration.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
    const studentProfile = getStudentProfile();
    const marks = studentProfile?.marks || [];

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-slate-800">Academic Transcript</h1>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Subject</th>
                            <th className="px-6 py-4">Mid-Term</th>
                            <th className="px-6 py-4">Finals</th>
                            <th className="px-6 py-4">Avg Score</th>
                            <th className="px-6 py-4">Grade</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {marks.length === 0 ? (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400">No grades available yet.</td></tr>
                        ) : (
                            marks.map((m, i) => {
                                const avg = (m.midTerm + m.final) / 2;
                                return (
                                    <tr key={i}>
                                        <td className="px-6 py-4 font-medium">{m.subject}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.midTerm}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.final}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800">{avg.toFixed(1)}</td>
                                        <td className={`px-6 py-4 font-bold ${avg >= 70 ? 'text-green-600' : 'text-red-500'}`}>
                                            {calculateGrade(avg)}
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {studentProfile && studentProfile.gradeAverage > 0 && (
                <div className="p-4 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-700 flex justify-between items-center">
                    <span>Cumulative Grade Average</span>
                    <span className="font-bold text-lg">{studentProfile.gradeAverage}%</span>
                </div>
            )}
        </div>
    )
  }

  return (
    <div className="space-y-6">
      <header className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex items-center gap-6">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-20 h-20 rounded-full border-4 border-white/30 bg-slate-700"
          />
          <div>
            <h1 className="text-3xl font-bold mb-1">Hello, {user.name}</h1>
            <p className="text-blue-100 font-mono opacity-80">{user.schoolID} • Class {user.className || 'N/A'}</p>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Recent Grades */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Award className="text-yellow-500" />
