          <div className="flex items-center justify-center py-6">
             <div className="relative h-32 w-32 rounded-full border-8 border-slate-100 flex items-center justify-center">
                <div className="absolute inset-0 border-8 border-blue-600 rounded-full border-t-transparent rotate-[-45deg]" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0 100%)' }}></div>
                <div className="text-center">
                    <span className="text-2xl font-bold text-slate-800">100%</span>
                    <p className="text-xs text-slate-400">Present</p>
                </div>
             </div>
          </div>
        </div>

        {/* Assignments */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 md:col-span-2">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Book className="text-purple-500" />
            Active Assignments
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-purple-100 text-purple-700 text-xs px-2 py-1 rounded">History</span>
                    <span className="text-xs text-slate-400">Due Tomorrow</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">World War II Essay</h3>
                <p className="text-sm text-slate-500 mt-1">Submit PDF via portal.</p>
            </div>
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded">Science</span>
                    <span className="text-xs text-slate-400">Due Friday</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">Lab Report: Chemistry</h3>
                <p className="text-sm text-slate-500 mt-1">Complete section 1-4.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;

import React, { useState, useEffect } from 'react';
import { User, UserRole, StudentRecord, HouseTeam } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredStudents, updateStudent, addStudent, removeStudent } from '../services/storage';
import { Shield, Plus, School, Trash2, Pencil, Users, GraduationCap, Filter } from 'lucide-react';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals' | 'teachers' | 'students'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedClass, setSelectedClass] = useState<string>('All');

  // Generic Form State (Used for Principals, Teachers, Students)
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingStudent, setEditingStudent] = useState<StudentRecord | null>(null); // For extra student fields

  // Form Fields
  const [formName, setFormName] = useState('');
  const [formID, setFormID] = useState('');
  const [formPassword, setFormPassword] = useState('');
  const [formClass, setFormClass] = useState('');
  const [formSubject, setFormSubject] = useState('');
  const [formDesignation, setFormDesignation] = useState('');
  const [formHouse, setFormHouse] = useState<HouseTeam>('');
  const [formPost, setFormPost] = useState('');

  // New Fields for Teachers
  const [formEmail, setFormEmail] = useState('');
  const [formContact, setFormContact] = useState('');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setUsers(getStoredUsers());
    setStudents(getStoredStudents());
  };

  // --- MODAL HANDLERS ---

  const openPrincipalModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
    }
    setShowAddModal(true);
  };

  const openTeacherModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
        setFormClass(user.assignedClass || '');
        setFormSubject(user.assignedSubject || '');
        setFormDesignation(user.designation || '');
        setFormHouse(user.house || '');
        setFormEmail(user.email || '');
        setFormContact(user.contactNumber || '');
    }
    setShowAddModal(true);
  };

  const openStudentModal = (studentRec?: StudentRecord) => {
    resetForm();
    if (studentRec) {
        setEditingStudent(studentRec);
        // Find associated user for password/login info
        const linkedUser = users.find(u => u.schoolID === studentRec.schoolID);
        setEditingUser(linkedUser || null);

        setFormName(studentRec.name);
        setFormID(studentRec.schoolID);
        setFormPassword(linkedUser?.password || '');
        setFormClass(studentRec.className);
        setFormHouse(studentRec.house || '');
        setFormPost(studentRec.studentPost || '');
    }
    setShowAddModal(true);
  };

  const resetForm = () => {
    setEditingUser(null);
    setEditingStudent(null);
    setFormName('');
    setFormID('');
    setFormPassword('');
    setFormClass('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
  };

  // --- SAVE HANDLERS ---

  const handleSavePrincipal = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
        const updated: User = { ...editingUser, name: formName, schoolID: formID, password: formPassword };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.PRINCIPAL,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=3b82f6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    e.preventDefault();

    // --- VALIDATION START ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formEmail && !emailRegex.test(formEmail)) {
        alert("Please enter a valid email address (e.g., teacher@school.com).");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (formContact && !phoneRegex.test(formContact)) {
        alert("Contact number must be exactly 10 digits.");
        return;
    }
    // --- VALIDATION END ---

    if (editingUser) {
        const updated: User = { 
            ...editingUser, 
            name: formName, 
            schoolID: formID, 
            password: formPassword,
            assignedClass: formClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact
        };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.TEACHER,
            assignedClass: formClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=8b5cf6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingStudent) {
        // --- EDIT EXISTING STUDENT ---
        const updatedRecord: StudentRecord = {
            ...editingStudent,
            name: formName,
            schoolID: formID,
            className: formClass,
            // Roll number is preserved, but updateStudent will recalculate if name changed order
            house: formHouse,
            studentPost: formPost
        };
        updateStudent(updatedRecord);

        if (editingUser) {
            const updatedUser: User = {
                ...editingUser,
                name: formName,
                schoolID: formID,
                password: formPassword,
                className: formClass,
                email: editingStudent.email
            };
            updateUser(updatedUser);
        }
    } else {
        // --- CREATE NEW STUDENT ---
        const newRecord: StudentRecord = {
            id: generateId('s'),
            name: formName,
            schoolID: formID,
            rollNumber: 0, // Will be auto-assigned
            className: formClass,
            attendanceToday: null,
            gradeAverage: 0,
            house: formHouse,
            studentPost: formPost,
            marks: []
        };
        addStudent(newRecord);

        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.STUDENT,
            className: formClass,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=f59e0b&color=fff`
        };
        addUser(newUser);
    }

    refreshData();
    setShowAddModal(false);
  };

  const handleDeleteUser = (user: User) => {
      if(window.confirm(`Delete user ${user.name}? This cannot be undone.`)) {
          removeUser(user.uid);
          // If student, remove record too
          if(user.role === UserRole.STUDENT) {
             const studentRec = students.find(s => s.schoolID === user.schoolID);
             if (studentRec) {
                 // Use centralized remover to handle roll numbers
                 removeStudent(studentRec.id);
             }
          }
          refreshData();
      }
  };

  // --- DATA FILTERING ---

  const principals = users.filter(u => u.role === UserRole.PRINCIPAL);
  const teachers = users.filter(u => u.role === UserRole.TEACHER);

  const allClasses = Array.from(new Set(students.map(s => s.className))).sort();
  const filteredStudents = selectedClass === 'All' 
    ? students 
    : students.filter(s => s.className === selectedClass);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Admin Console</h1>
          <p className="text-slate-500">Full System Control & Data Management</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm">
            <button 
                onClick={() => setActiveTab('overview')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'overview' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Overview
            </button>
            <button 
                onClick={() => setActiveTab('principals')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'principals' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Principals
            </button>
            <button 
                onClick={() => setActiveTab('teachers')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'teachers' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Teachers
            </button>
            <button 
                onClick={() => setActiveTab('students')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'students' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Students
            </button>
        </div>
      </header>

      {/* OVERVIEW TAB */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-blue-100 w-fit rounded-lg mb-4">
              <School className="text-blue-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Principals</h3>
            <p className="text-3xl font-bold text-slate-800">{principals.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-purple-100 w-fit rounded-lg mb-4">
              <Users className="text-purple-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Teachers</h3>
            <p className="text-3xl font-bold text-slate-800">{teachers.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
             <div className="p-3 bg-green-100 w-fit rounded-lg mb-4">
              <GraduationCap className="text-green-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Students</h3>
            <p className="text-3xl font-bold text-slate-800">{students.length}</p>
          </div>
        </div>
      )}

      {/* PRINCIPALS TAB */}
      {activeTab === 'principals' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Principal Management</h2>
            <button onClick={() => openPrincipalModal()} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              <Plus size={18} /> Add Principal
            </button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">School ID</th>
                <th className="px-6 py-4">Password</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {principals.map(p => (
                <tr key={p.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium flex items-center gap-3">
                    <img src={p.avatarUrl} className="w-8 h-8 rounded-full" /> {p.name}
                  </td>
                  <td className="px-6 py-4 font-mono text-slate-600">{p.schoolID}</td>
                  <td className="px-6 py-4 font-mono text-slate-400 text-sm">{p.password}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openPrincipalModal(p)} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Pencil size={18} /></button>
                    <button onClick={() => handleDeleteUser(p)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* TEACHERS TAB */}
      {activeTab === 'teachers' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Teacher Management</h2>
            <button onClick={() => openTeacherModal()} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              <Plus size={18} /> Add Teacher
            </button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">House</th>
                <th className="px-6 py-4">Designation</th>
                <th className="px-6 py-4">Class/Sub</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {teachers.map(t => (
                <tr key={t.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium flex items-center gap-3">
                    <img src={t.avatarUrl} className="w-8 h-8 rounded-full" /> {t.name}
                  </td>
                  <td className="px-6 py-4 font-mono text-slate-600">{t.schoolID}</td>
                  <td className="px-6 py-4 text-sm">{t.house || '-'}</td>
                  <td className="px-6 py-4 text-sm font-semibold text-slate-700">{t.designation || '-'}</td>
                  <td className="px-6 py-4 text-sm text-slate-500">{t.assignedClass} / {t.assignedSubject}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openTeacherModal(t)} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Pencil size={18} /></button>
                    <button onClick={() => handleDeleteUser(t)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* STUDENTS TAB */}
      {activeTab === 'students' && (
        <div className="space-y-4">
            <div className="flex justify-between items-center">
                <div className="flex items-center gap-4 bg-white p-2 rounded-lg border border-slate-200 shadow-sm">
                    <Filter size={18} className="text-slate-400 ml-2" />
                    <span className="text-sm font-medium text-slate-600">Filter by Class:</span>
                    <select 
                        value={selectedClass} 
                        onChange={e => setSelectedClass(e.target.value)}
                        className="bg-transparent text-sm font-bold text-slate-800 outline-none cursor-pointer"
                    >
                        <option value="All">All Classes</option>
                        {allClasses.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <button onClick={() => openStudentModal()} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
                    <Plus size={18} /> Add Student
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100">
                    <tr>
                        <th className="px-6 py-4">Name</th>
                        <th className="px-6 py-4">Class</th>
                        <th className="px-6 py-4">Roll</th>
                        <th className="px-6 py-4">ID</th>
                        <th className="px-6 py-4">House</th>
                        <th className="px-6 py-4">Post</th>
                        <th className="px-6 py-4 text-right">Edit</th>
                    </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                    {filteredStudents.length === 0 ? (
                        <tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>
                    ) : (
                        filteredStudents.map(s => (
                        <tr key={s.id} className="hover:bg-slate-50">
                            <td className="px-6 py-4 font-medium">{s.name}</td>
                            <td className="px-6 py-4 text-slate-600">{s.className}</td>
                            <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                            <td className="px-6 py-4 font-mono text-sm text-slate-500">{s.schoolID}</td>
                            <td className="px-6 py-4 text-sm font-bold uppercase text-slate-600">{s.house || '-'}</td>
                            <td className="px-6 py-4 text-sm text-purple-600 font-medium">{s.studentPost || '-'}</td>
                            <td className="px-6 py-4 text-right">
                                <button onClick={() => openStudentModal(s)} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Pencil size={18} /></button>
                            </td>
                        </tr>
                        ))
                    )}
                    </tbody>
                </table>
            </div>
        </div>
      )}

      {/* SHARED MODAL */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
          <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
            <button onClick={() => setShowAddModal(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 text-xl">&times;</button>

            <h2 className="text-xl font-bold mb-6">
                {activeTab === 'principals' && (editingUser ? 'Edit Principal' : 'New Principal')}
                {activeTab === 'teachers' && (editingUser ? 'Edit Teacher' : 'New Teacher')}
                {activeTab === 'students' && (editingStudent ? 'Edit Student' : 'Add New Student')}
            </h2>

            <form onSubmit={
                activeTab === 'principals' ? handleSavePrincipal :
                activeTab === 'teachers' ? handleSaveTeacher :
                handleSaveStudent
            } className="space-y-4">

              {/* Common Fields */}
              <div>
                  <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Full Name</label>
                  <input className="w-full px-4 py-2 border rounded-lg" value={formName} onChange={e => setFormName(e.target.value)} required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">School ID</label>
                      <input className="w-full px-4 py-2 border rounded-lg font-mono" value={formID} onChange={e => setFormID(e.target.value)} required />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Password</label>
                      <input className="w-full px-4 py-2 border rounded-lg" value={formPassword} onChange={e => setFormPassword(e.target.value)} required />
                  </div>
              </div>

              {/* Teacher Specifics */}
              {activeTab === 'teachers' && (
                  <>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Class</label>
                            <input className="w-full px-4 py-2 border rounded-lg" value={formClass} onChange={e => setFormClass(e.target.value)} placeholder="e.g 10-A" />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Subject</label>
                            <input className="w-full px-4 py-2 border rounded-lg" value={formSubject} onChange={e => setFormSubject(e.target.value)} placeholder="e.g Math" />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Designation</label>
                          <input className="w-full px-4 py-2 border rounded-lg" value={formDesignation} onChange={e => setFormDesignation(e.target.value)} placeholder="e.g. H.O.D" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">House Team</label>
                          <select
                              className="w-full px-4 py-2 border rounded-lg"
                              value={formHouse}
                              onChange={(e) => setFormHouse(e.target.value as HouseTeam)}
                          >
                              <option value="">None</option>
                              <option value="Palash">Palash (Green)</option>
                              <option value="Amaltash">Amaltash (Blue)</option>
                              <option value="Devdar">Devdar (Yellow)</option>
                              <option value="Gulmohar">Gulmohar (Red)</option>
                          </select>
                      </div>
                    </div>

                    {/* New Contact Info Section */}
                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-100">
                        <label className="block text-xs font-bold text-slate-500 mb-2 uppercase border-b border-slate-200 pb-1">Contact Details</label>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs text-slate-500 mb-1">Email Address</label>
                                <input 
                                    type="email" 
                                    className="w-full px-4 py-2 border rounded-lg" 
                                    value={formEmail} 
                                    onChange={e => setFormEmail(e.target.value)} 
                                    placeholder="teacher@school.edu" 
                                />
                            </div>
                            <div>
                                <label className="block text-xs text-slate-500 mb-1">Phone Number</label>
                                <input 
                                    type="tel"
                                    maxLength={10}
                                    className="w-full px-4 py-2 border rounded-lg" 
                                    value={formContact} 
                                    onChange={e => setFormContact(e.target.value)} 
                                    placeholder="e.g. 9876543210" 
                                />
                            </div>
                        </div>
                    </div>
                  </>
              )}

              {/* Student Specifics */}
              {activeTab === 'students' && (
                  <>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Class</label>
                        <input className="w-full px-4 py-2 border rounded-lg" value={formClass} onChange={e => setFormClass(e.target.value)} required />
                    </div>

                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-100">
                      <label className="block text-xs font-bold text-slate-500 mb-2 uppercase border-b border-slate-200 pb-1">Additional Roles</label>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs text-slate-500 mb-1">House Team</label>
                              <select
                                  className="w-full px-4 py-2 border rounded-lg bg-white"
                                  value={formHouse}
                                  onChange={(e) => setFormHouse(e.target.value as HouseTeam)}
                              >
                                  <option value="">None</option>
                                  <option value="Palash">Palash</option>
                                  <option value="Amaltash">Amaltash</option>
                                  <option value="Devdar">Devdar</option>
                                  <option value="Gulmohar">Gulmohar</option>
                              </select>
                          </div>
                          <div>
                              <label className="block text-xs text-slate-500 mb-1">Student Post</label>
                              <input className="w-full px-4 py-2 border rounded-lg" value={formPost} onChange={e => setFormPost(e.target.value)} placeholder="e.g Head Boy" />
                          </div>
                      </div>
                    </div>
                  </>
              )}

              <div className="flex gap-3 pt-6 border-t border-slate-100 mt-4">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 border rounded-lg hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { StudentRecord, User, UserRole, MarkEntry, Announcement, HouseTeam } from '../types';
import { getStoredStudents, addStudent, updateStudent, generateId, getStoredUsers, addUser, updateUser, getStoredAnnouncements, saveAllStudents } from '../services/storage';
import { CheckSquare, Square, Save, UserPlus, Pencil, GraduationCap, Plus, Trash2, Megaphone, SortAsc, Calendar, Shield, Flag, User as UserIcon } from 'lucide-react';

interface Props {
  currentPage?: string;
  currentUser: User;
}

const TeacherDashboard: React.FC<Props> = ({ currentPage = 'dashboard', currentUser }) => {
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [hasChanges, setHasChanges] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  // Profile Edit State
  const [editHouseMode, setEditHouseMode] = useState(false);
  const [selectedHouse, setSelectedHouse] = useState<HouseTeam>(currentUser.house || '');

  // Student Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('Male'); 
  const [schoolID, setSchoolID] = useState('');
  const [password, setPassword] = useState(''); 
  const [className, setClassName] = useState('10-A');
  const [email, setEmail] = useState('');
  const [fatherContact, setFatherContact] = useState('');
  const [motherContact, setMotherContact] = useState('');
  const [house, setHouse] = useState<HouseTeam>('');
  const [studentPost, setStudentPost] = useState('');

  // Marks Form State
  const [showMarksModal, setShowMarksModal] = useState(false);
  const [currentMarksStudent, setCurrentMarksStudent] = useState<StudentRecord | null>(null);
  const [marksList, setMarksList] = useState<MarkEntry[]>([]);
  const [newSubject, setNewSubject] = useState('');
  const [newMidTerm, setNewMidTerm] = useState('');
  const [newFinal, setNewFinal] = useState('');

  useEffect(() => {
    // Load students and sort by roll number initially for display consistency
    const loadedStudents = getStoredStudents();
    const sortedStudents = loadedStudents.sort((a, b) => a.rollNumber - b.rollNumber);
    setStudents(sortedStudents);

    setUsers(getStoredUsers());

    // Fetch and filter announcements
    const allAnn = getStoredAnnouncements();
    const relevantAnn = allAnn.filter(a => a.audience === 'all' || a.audience === 'teacher');
    setAnnouncements(relevantAnn);
  }, []);

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setDob(newDob);
    const calculatedAge = calculateAge(newDob);
    setAge(calculatedAge);
  };

  const handleToggleAttendance = (id: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, attendanceToday: s.attendanceToday === false ? true : false }; 
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllPresent = () => {
    setStudents(prev => prev.map(s => ({ ...s, attendanceToday: true })));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    students.forEach(s => updateStudent(s));
    setHasChanges(false);
    alert("Attendance saved to database!");
  };

  const updateOwnHouse = () => {
      const updatedUser = { ...currentUser, house: selectedHouse };
      updateUser(updatedUser);
      setEditHouseMode(false);
      alert("House updated successfully. Please re-login to see changes in sidebar.");
  };

  // --- STUDENT MODAL LOGIC ---

  const openAddModal = () => {
    setEditingId(null);
    setName('');
    setAge('');
    setDob('');
    setGender('Male');
    setSchoolID('');
    setPassword('');
    setClassName(currentUser.assignedClass || '10-A');
    setEmail('');
    setFatherContact('');
    setMotherContact('');
    setHouse('');
    setStudentPost('');
    setShowModal(true);
  };

  const openEditModal = (student: StudentRecord) => {
    setEditingId(student.id);
    const userLogin = users.find(u => u.schoolID === student.schoolID);

    setName(student.name);
    setAge(student.age?.toString() || '');
    setDob(student.dob || '');
    setGender(student.gender || 'Male');
    setSchoolID(student.schoolID);
    setPassword(userLogin?.password || '');
    setClassName(student.className);
    setEmail(student.email || '');
    setFatherContact(student.fatherContact || '');
    setMotherContact(student.motherContact || '');
    setHouse(student.house || '');
    setStudentPost(student.studentPost || '');
    setShowModal(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();

    // --- VALIDATION START ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email && !emailRegex.test(email)) {
        alert("Please enter a valid school email address (e.g., student@school.edu).");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (fatherContact && !phoneRegex.test(fatherContact)) {
        alert("Father's contact number must be exactly 10 digits.");
        return;
    }
    if (motherContact && !phoneRegex.test(motherContact)) {
        alert("Mother's contact number must be exactly 10 digits.");
        return;
    }
    // --- VALIDATION END ---

    let updatedList = [...getStoredStudents()];

    if (editingId) {
      // Update existing
      const existingIndex = updatedList.findIndex(s => s.id === editingId);
      if (existingIndex === -1) return;

      const existingStudent = updatedList[existingIndex];

      const updatedRecord: StudentRecord = {
        ...existingStudent,
        name,
        schoolID,
        className,
        age: parseInt(age),
        dob,
        gender,
        email,
        fatherContact,
        motherContact,
        house,
        studentPost
        // rollNumber is preserved and handled by updateStudent
      };

      // Update via storage service which handles sorting
      updateStudent(updatedRecord);

      // Update associated User account
      const associatedUser = users.find(u => u.schoolID === existingStudent.schoolID);
      if (associatedUser) {
        const updatedUser: User = {
          ...associatedUser,
          name,
          schoolID,
          password,
          className,
          gender,
          dob,
          email: email
        };
        updateUser(updatedUser);
      }

      alert(`Student ${name} updated successfully.`);

    } else {
      // Create new
      const newRecord: StudentRecord = {
        id: generateId('s'),
        name,
        schoolID,
        rollNumber: 0, // Placeholder, will be auto-assigned
        attendanceToday: null,
        gradeAverage: 0,
        className,
        age: parseInt(age),
        dob,
        gender,
        email,
        fatherContact,
        motherContact,
        marks: [],
        house,
        studentPost
      };

      // Add via storage service which handles sorting
      addStudent(newRecord);

      const newUser: User = {
        uid: generateId('u'),
        name,
        schoolID,
        role: UserRole.STUDENT,
        className,
        password,
        gender,
        dob,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f59e0b&color=fff`
      };

      addUser(newUser);
      alert(`Student Added! Login ID: ${schoolID}, Password: ${password}`);
    }

    // Refresh Local State
    setStudents(getStoredStudents().sort((a, b) => a.rollNumber - b.rollNumber));
    setUsers(getStoredUsers());
    setShowModal(false);
  };

  // --- MARKS LOGIC ---

  const openMarksModal = (student: StudentRecord) => {
    setCurrentMarksStudent(student);
    setMarksList(student.marks || []);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
    setShowMarksModal(true);
  };

  const handleAddMark = () => {
    if (!newSubject || !newMidTerm || !newFinal) {
        alert("Please fill all fields.");
        return;
    }
    const newEntry: MarkEntry = {
        subject: newSubject,
        midTerm: parseFloat(newMidTerm),
        final: parseFloat(newFinal)
    };
    setMarksList([...marksList, newEntry]);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
  };

  const handleRemoveMark = (index: number) => {
    const updated = [...marksList];
    updated.splice(index, 1);
    setMarksList(updated);
  };

  const saveMarks = () => {
    if (!currentMarksStudent) return;

    // Calculate new average
    let totalScore = 0;
    let count = 0;
    marksList.forEach(m => {
        totalScore += (m.midTerm + m.final) / 2;
        count++;
    });
    const newAverage = count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0;

    const updatedStudent: StudentRecord = {
        ...currentMarksStudent,
        marks: marksList,
        gradeAverage: newAverage
    };

    updateStudent(updatedStudent);
    // Refresh list from storage and sort
    setStudents(getStoredStudents().sort((a, b) => a.rollNumber - b.rollNumber));
    setShowMarksModal(false);
    alert(`Marks updated for ${currentMarksStudent.name}`);
  };

  const getHouseColor = (house?: HouseTeam) => {
    switch(house) {
        case 'Palash': return 'bg-green-100 text-green-700 border-green-200';
        case 'Amaltash': return 'bg-blue-100 text-blue-700 border-blue-200';
        case 'Devdar': return 'bg-yellow-100 text-yellow-700 border-yellow-200';
        case 'Gulmohar': return 'bg-red-100 text-red-700 border-red-200';
        default: return 'bg-slate-50 text-slate-500 border-slate-100';
    }
  };

  // --- RENDERING ---

  if (currentPage === 'profile') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
                 <p className="text-slate-500">Manage your personal details and settings.</p>
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden max-w-2xl">
                 <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6 bg-slate-50">
                    <img 
                        src={currentUser.avatarUrl} 
                        alt={currentUser.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left">
                        <h2 className="text-2xl font-bold text-slate-900">{currentUser.name}</h2>
                        <p className="text-slate-500 font-mono text-sm">{currentUser.schoolID} • {currentUser.designation || 'Teacher'}</p>
                    </div>
                 </div>

                 <div className="p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div>
                             <label className="block text-xs text-slate-400 font-bold uppercase mb-1">Class Assigned</label>
                             <p className="text-lg font-medium text-slate-800">{currentUser.assignedClass || 'N/A'}</p>
                         </div>
                         <div>
                             <label className="block text-xs text-slate-400 font-bold uppercase mb-1">Subject</label>
                             <p className="text-lg font-medium text-slate-800">{currentUser.assignedSubject || 'N/A'}</p>
                         </div>
                    </div>

                    <div className="pt-6 border-t border-slate-100">
                         <div className="flex justify-between items-center mb-4">
                             <h3 className="text-sm font-bold text-slate-700 uppercase flex items-center gap-2">
                                <Flag size={16} /> House Team
                             </h3>
                             {!editHouseMode && (
                                 <button 
                                    onClick={() => setEditHouseMode(true)}
                                    className="text-xs text-blue-600 hover:text-blue-800 font-medium"
                                 >
                                     Change House
                                 </button>
                             )}
                         </div>

                         {editHouseMode ? (
                             <div className="flex items-center gap-3">
                                 <select 
                                    className="flex-1 px-4 py-2 border rounded-lg focus:outline-none focus:border-blue-500"
                                    value={selectedHouse}
                                    onChange={(e) => setSelectedHouse(e.target.value as HouseTeam)}
                                 >
                                    <option value="">Select House</option>
                                    <option value="Palash">Palash (Green)</option>
                                    <option value="Amaltash">Amaltash (Blue)</option>
                                    <option value="Devdar">Devdar (Yellow)</option>
                                    <option value="Gulmohar">Gulmohar (Red)</option>
                                 </select>
                                 <button onClick={updateOwnHouse} className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">Save</button>
                                 <button onClick={() => setEditHouseMode(false)} className="px-4 py-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300">Cancel</button>
                             </div>
                         ) : (
                             <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(currentUser.house as HouseTeam)}`}>
                                 {currentUser.house || 'No House Assigned'}
                             </div>
                         )}
                    </div>
                 </div>
              </div>
          </div>
      );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">School-wide announcements and teacher updates.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">Student Grades</h1>
                    <p className="text-slate-500">Manage Assessments & Results</p>
                </div>
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Student Name</th>
                            <th className="px-6 py-4">Roll No</th>
                            <th className="px-6 py-4">Overall GPA</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {students.length === 0 ? (
                             <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>
                        ) : (
                            students.map(s => (
                                <tr key={s.id} className="hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium">{s.name}</td>
                                    <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                                    <td className="px-6 py-4 font-bold text-blue-600">
                                        {s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button 
                                            onClick={() => openMarksModal(s)}
                                            className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 transition-colors flex items-center gap-2 ml-auto"
                                        >
                                            <GraduationCap size={16} /> Manage Marks
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
              </div>

              {/* Marks Modal */}
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                    <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl">
