                                    type="tel"
                                    maxLength={10}
                                    className="w-full px-4 py-2 border rounded-lg" 
                                    value={formContact} 
                                    onChange={e => setFormContact(e.target.value)} 
                                    placeholder="e.g. 9876543210" 
                                />
                            </div>
                        </div>
                    </div>
                  </>
              )}

              {/* Student Specifics */}
              {activeTab === 'students' && (
                  <>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Class Grade</label>
                            <select 
                                className="w-full px-4 py-2 border rounded-lg"
                                value={formGrade}
                                onChange={e => {
                                    setFormGrade(e.target.value);
                                    setFormSection('');
                                }}
