                                onChange={handleDobChange}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Age (Auto)</label>
                            <input 
                                className="w-full px-4 py-2 border rounded-lg bg-slate-50" 
                                value={formAge}
