import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredStudents, updateStudent, addStudent, removeStudent, getStoredAnnouncements, addAnnouncement, deleteAnnouncement } from '../services/storage';
import { Shield, Plus, School, Trash2, Pencil, Users, GraduationCap, Filter, AlertCircle, Megaphone, Send, UserCog, Building2 } from 'lucide-react';
import { CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR, SCHOOL_NAMES } from '../constants';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals' | 'teachers' | 'students' | 'announcements'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  const [showAddModal, setShowAddModal] = useState(false);
  const [showAnnModal, setShowAnnModal] = useState(false);
  const [selectedClass, setSelectedClass] = useState<string>('All');

  // Generic Form State (Used for Principals, Teachers, Students)
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingStudent, setEditingStudent] = useState<StudentRecord | null>(null); // For extra student fields

  // Error State
  const [formError, setFormError] = useState('');

  // Form Fields
  const [formName, setFormName] = useState('');
  const [formID, setFormID] = useState('');
  const [formPassword, setFormPassword] = useState('');

  // School Assignment State
  const [formSchool, setFormSchool] = useState(''); 
  const [formPrincipalId, setFormPrincipalId] = useState(''); // For assigning teacher to principal

  // Class Split State
  const [formGrade, setFormGrade] = useState('');
  const [formSection, setFormSection] = useState('');

  const [formSubject, setFormSubject] = useState('');
  const [formDesignation, setFormDesignation] = useState('');
  const [formHouse, setFormHouse] = useState<HouseTeam>('');
  const [formPost, setFormPost] = useState('');

  // Extended Fields (Teachers & Students)
  const [formEmail, setFormEmail] = useState('');
  const [formContact, setFormContact] = useState(''); // Teachers contact

  // Student Specific Extended Fields
  const [formDob, setFormDob] = useState('');
  const [formAge, setFormAge] = useState('');
  const [formGender, setFormGender] = useState('Male');
  const [formFatherContact, setFormFatherContact] = useState('');
  const [formMotherContact, setFormMotherContact] = useState('');

  // Announcement Form State
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [annAudience, setAnnAudience] = useState<'all' | 'student' | 'teacher'>('all');
  const [annSpoofType, setAnnSpoofType] = useState<'admin' | 'impersonate' | 'custom'>('admin');
  const [annImpersonateId, setAnnImpersonateId] = useState('');
  const [annCustomName, setAnnCustomName] = useState('');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setUsers(getStoredUsers());
    setStudents(getStoredStudents());
    setAnnouncements(getStoredAnnouncements());
  };

  // Helper to parse "Grade-Section" string
  const parseClassString = (classStr: string) => {
    if (!classStr) return { grade: '', section: '' };
    // Assuming format "Grade-Section"
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        // Rejoin rest as section in case section has hyphens (though unlikely with current options)
        return { grade: parts[0], section: parts.slice(1).join('-') };
    }
    return { grade: classStr, section: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setFormDob(newDob);
    setFormAge(calculateAge(newDob));
  };

  // --- MODAL HANDLERS ---

  const openPrincipalModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
        setFormSchool(user.schoolName || '');
    }
    setShowAddModal(true);
  };

  const openTeacherModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');

        // When editing, we show the school, but maybe not the principal selector if already assigned
        setFormSchool(user.schoolName || '');

        const { grade, section } = parseClassString(user.assignedClass || '');
        setFormGrade(grade);
        setFormSection(section);

        setFormSubject(user.assignedSubject || '');
        setFormDesignation(user.designation || '');
        setFormHouse(user.house || '');
        setFormEmail(user.email || '');
        setFormContact(user.contactNumber || '');
    }
    setShowAddModal(true);
  };

  const openStudentModal = (studentRec?: StudentRecord) => {
    resetForm();
    if (studentRec) {
        setEditingStudent(studentRec);
        // Find associated user for password/login info
        const linkedUser = users.find(u => u.schoolID === studentRec.schoolID);
        setEditingUser(linkedUser || null);

        setFormName(studentRec.name);
        setFormID(studentRec.schoolID);
        setFormPassword(linkedUser?.password || '');
        setFormSchool(studentRec.schoolName || '');

        const { grade, section } = parseClassString(studentRec.className);
        setFormGrade(grade);
        setFormSection(section);

        setFormHouse(studentRec.house || '');
        setFormPost(studentRec.studentPost || '');

        // Extended Student Fields
        setFormDob(studentRec.dob || '');
        setFormAge(studentRec.age?.toString() || '');
        setFormGender(studentRec.gender || 'Male');
        setFormEmail(studentRec.email || '');
        setFormFatherContact(studentRec.fatherContact || '');
        setFormMotherContact(studentRec.motherContact || '');
    } else {
        // Defaults for new student
        setFormGender('Male');
    }
    setShowAddModal(true);
  };

  const openAnnouncementModal = () => {
      setAnnTitle('');
      setAnnContent('');
      setAnnAudience('all');
      setAnnSpoofType('admin');
      setAnnImpersonateId('');
      setAnnCustomName('');
      setShowAnnModal(true);
  };

  const resetForm = () => {
    setEditingUser(null);
    setEditingStudent(null);
    setFormError('');
    setFormName('');
    setFormID('');
    setFormPassword('');
    setFormGrade('');
    setFormSection('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
    setFormSchool('');
    setFormPrincipalId('');

    // Student Extra
    setFormDob('');
    setFormAge('');
    setFormGender('Male');
    setFormFatherContact('');
    setFormMotherContact('');
  };

  // --- SAVE HANDLERS ---

  const handleSavePrincipal = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!formSchool) {
        setFormError("Please assign a School to the Principal.");
        return;
    }

    // Check Duplicate ID
    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingUser) {
        const updated: User = { 
            ...editingUser, 
            name: formName, 
            schoolID: formID, 
            password: formPassword,
            schoolName: formSchool 
        };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.PRINCIPAL,
            schoolName: formSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=3b82f6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    // If new teacher, enforce principal assignment which dictates school
    let derivedSchool = formSchool;
    if (!editingUser) {
        if (!formPrincipalId) {
            setFormError("Please assign the teacher to a Principal.");
            return;
        }
        const assignedPrincipal = users.find(u => u.uid === formPrincipalId);
        if (assignedPrincipal && assignedPrincipal.schoolName) {
            derivedSchool = assignedPrincipal.schoolName;
        } else {
            setFormError("Selected Principal does not have a valid School assigned.");
            return;
        }
    }

    if (!formGrade || !formSection) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${formGrade}-${formSection}`;

    // Validations
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formEmail && !emailRegex.test(formEmail)) {
        setFormError("Invalid email format. Please enter a valid email address.");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (formContact && !phoneRegex.test(formContact)) {
        setFormError("Contact number must be exactly 10 digits.");
        return;
    }

    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingUser) {
        const updated: User = { 
            ...editingUser, 
            name: formName, 
            schoolID: formID, 
            password: formPassword,
            assignedClass: fullClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact,
            schoolName: derivedSchool // Maintain or update school
        };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.TEACHER,
            assignedClass: fullClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact,
            schoolName: derivedSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=8b5cf6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!formSchool) {
        setFormError("Please assign a School to the Student.");
        return;
    }

    if (!formGrade || !formSection) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${formGrade}-${formSection}`;

    // --- VALIDATION ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formEmail && !emailRegex.test(formEmail)) {
        setFormError("Please enter a valid school email address.");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (formFatherContact && !phoneRegex.test(formFatherContact)) {
        setFormError("Father's contact must be 10 digits.");
        return;
    }
    if (formMotherContact && !phoneRegex.test(formMotherContact)) {
        setFormError("Mother's contact must be 10 digits.");
        return;
    }

    // Check Duplicate ID
    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingStudent) {
        // --- EDIT EXISTING STUDENT ---
        const updatedRecord: StudentRecord = {
            ...editingStudent,
            name: formName,
            schoolID: formID,
            className: fullClass,
            // Roll number is preserved, but updateStudent will recalculate if name changed order
            house: formHouse,
            studentPost: formPost,
            // Extended Fields
            dob: formDob,
            age: parseInt(formAge) || 0,
            gender: formGender,
            email: formEmail,
            fatherContact: formFatherContact,
            motherContact: formMotherContact,
            schoolName: formSchool
        };
        updateStudent(updatedRecord);

        if (editingUser) {
            const updatedUser: User = {
                ...editingUser,
                name: formName,
                schoolID: formID,
                password: formPassword,
                className: fullClass,
                email: formEmail,
                gender: formGender,
                dob: formDob,
                schoolName: formSchool
            };
            updateUser(updatedUser);
        }
    } else {
        // --- CREATE NEW STUDENT ---
        const newRecord: StudentRecord = {
            id: generateId('s'),
            name: formName,
            schoolID: formID,
            rollNumber: 0, // Will be auto-assigned
            className: fullClass,
            attendanceToday: null,
            gradeAverage: 0,
            house: formHouse,
            studentPost: formPost,
            marks: [],
            // Extended Fields
            dob: formDob,
            age: parseInt(formAge) || 0,
            gender: formGender,
            email: formEmail,
            fatherContact: formFatherContact,
            motherContact: formMotherContact,
            schoolName: formSchool
        };
        addStudent(newRecord);

        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.STUDENT,
            className: fullClass,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=f59e0b&color=fff`,
            // User Extended
            email: formEmail,
            gender: formGender,
            dob: formDob,
            schoolName: formSchool
        };
        addUser(newUser);
    }

    refreshData();
    setShowAddModal(false);
  };

  const handlePostAnnouncement = (e: React.FormEvent) => {
      e.preventDefault();

      // DETERMINE AUTHOR NAME (Identity Spoofing)
      let authorName = 'System Administrator';
      if (annSpoofType === 'impersonate' && annImpersonateId) {
          const userToImpersonate = users.find(u => u.uid === annImpersonateId);
          if (userToImpersonate) {
              authorName = userToImpersonate.name;
          }
      } else if (annSpoofType === 'custom' && annCustomName) {
          authorName = annCustomName;
      }

      const newAnn: Announcement = {
          id: generateId('ann'),
          title: annTitle,
          content: annContent,
          date: new Date().toISOString().split('T')[0],
          audience: annAudience,
          author: authorName // This is the spoofed identity
      };

      addAnnouncement(newAnn);
      refreshData();
      setShowAnnModal(false);
  };

  const handleDeleteUser = (user: User) => {
      if(window.confirm(`Delete user ${user.name}? This cannot be undone.`)) {
          // Remove from Users table
          removeUser(user.uid);

          // If student, remove from Students table as well
          if(user.role === UserRole.STUDENT) {
             const freshStudents = getStoredStudents(); // Fetch fresh to avoid stale state
             const studentRec = freshStudents.find(s => s.schoolID === user.schoolID);
             if (studentRec) {
                 removeStudent(studentRec.id);
             }
          }
          refreshData();
      }
  };

  const handleDeleteAnnouncement = (id: string) => {
      if(window.confirm('Delete this announcement globally?')) {
          deleteAnnouncement(id);
          refreshData();
      }
  }

  // Delete handler for Modal
  const handleDeleteFromModal = (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const freshUsers = getStoredUsers();
      const freshStudents = getStoredStudents();

      // Determine what we are deleting based on activeTab
      if (activeTab === 'students' && editingStudent) {
         if(window.confirm(`Delete student ${editingStudent.name}? This cannot be undone.`)) {
             // 1. Remove Student Record
             removeStudent(editingStudent.id);

             // 2. Remove Linked User Account
             const linkedUser = freshUsers.find(u => u.schoolID === editingStudent.schoolID);
             if (linkedUser) {
                 removeUser(linkedUser.uid);
             }
             refreshData();
             setShowAddModal(false);
         }
      } else if (editingUser) {
          // Principals or Teachers
          if(window.confirm(`Delete user ${editingUser.name}? This cannot be undone.`)) {
              // 1. Remove User Account
              removeUser(editingUser.uid);

              // 2. Check if it was a student and remove record if so (Cleanup)
              if(editingUser.role === UserRole.STUDENT) {
                  const studentRec = freshStudents.find(s => s.schoolID === editingUser.schoolID);
                  if (studentRec) removeStudent(studentRec.id);
              }
              refreshData();
              setShowAddModal(false);
          }
      }
  };

  // --- DATA FILTERING ---

  const principals = users.filter(u => u.role === UserRole.PRINCIPAL);
  const teachers = users.filter(u => u.role === UserRole.TEACHER);
  // List of potential targets for impersonation (Staff only usually, but let's include all non-students for now or just staff)
  const impersonationTargets = [...principals, ...teachers].sort((a, b) => a.name.localeCompare(b.name));

  const allClasses = Array.from(new Set(students.map(s => s.className))).sort();
  const filteredStudents = selectedClass === 'All' 
    ? students 
    : students.filter(s => s.className === selectedClass);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Admin Console</h1>
          <p className="text-slate-500">Full System Control & Data Management</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm">
            <button 
                onClick={() => setActiveTab('overview')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'overview' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Overview
            </button>
            <button 
                onClick={() => setActiveTab('principals')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'principals' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Principals
            </button>
            <button 
                onClick={() => setActiveTab('teachers')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'teachers' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Teachers
            </button>
            <button 
                onClick={() => setActiveTab('students')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'students' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                Students
            </button>
            <button 
                onClick={() => setActiveTab('announcements')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors flex items-center gap-2 ${activeTab === 'announcements' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <Megaphone size={16} /> Posts
            </button>
        </div>
      </header>

      {/* OVERVIEW TAB */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-blue-100 w-fit rounded-lg mb-4">
              <School className="text-blue-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Principals</h3>
            <p className="text-3xl font-bold text-slate-800">{principals.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-purple-100 w-fit rounded-lg mb-4">
              <Users className="text-purple-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Teachers</h3>
            <p className="text-3xl font-bold text-slate-800">{teachers.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
             <div className="p-3 bg-green-100 w-fit rounded-lg mb-4">
              <GraduationCap className="text-green-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Students</h3>
            <p className="text-3xl font-bold text-slate-800">{students.length}</p>
          </div>
        </div>
      )}

      {/* PRINCIPALS TAB */}
      {activeTab === 'principals' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Principal Management</h2>
            <button onClick={() => openPrincipalModal()} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              <Plus size={18} /> Add Principal
            </button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">School</th>
                <th className="px-6 py-4">School ID</th>
                <th className="px-6 py-4">Password</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {principals.map(p => (
                <tr key={p.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium flex items-center gap-3">
                    <img src={p.avatarUrl} className="w-8 h-8 rounded-full" /> {p.name}
                  </td>
                   <td className="px-6 py-4 text-sm font-semibold text-blue-700">
                      {p.schoolName || 'Unassigned'}
                   </td>
                  <td className="px-6 py-4 font-mono text-slate-600">{p.schoolID}</td>
                  <td className="px-6 py-4 font-mono text-slate-400 text-sm">{p.password}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openPrincipalModal(p)} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Pencil size={18} /></button>
                    <button onClick={() => handleDeleteUser(p)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* TEACHERS TAB */}
      {activeTab === 'teachers' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Teacher Management</h2>
            <button onClick={() => openTeacherModal()} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              <Plus size={18} /> Add Teacher
            </button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">School</th>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">Designation</th>
                <th className="px-6 py-4">Class/Sub</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {teachers.map(t => (
                <tr key={t.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium flex items-center gap-3">
                    <img src={t.avatarUrl} className="w-8 h-8 rounded-full" /> {t.name}
                  </td>
                  <td className="px-6 py-4 text-sm font-semibold text-blue-700">
