                )}
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 border rounded-lg hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { User, StudentRecord, MarkEntry, Announcement, HouseTeam, UserRole } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash, Megaphone, Calendar, Shield, Flag } from 'lucide-react';
import { getStoredStudents, getStoredAnnouncements, getStoredUsers } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  useEffect(() => {
     const allAnn = getStoredAnnouncements();
     const relevantAnn = allAnn.filter(a => a.audience === 'all' || a.audience === 'student');
     setAnnouncements(relevantAnn);
  }, []);

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

   const getHouseColor = (house?: HouseTeam) => {
    switch(house) {
        case 'Palash': return 'text-green-600 bg-green-50 border-green-200';
        case 'Amaltash': return 'text-blue-600 bg-blue-50 border-blue-200';
        case 'Devdar': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
        case 'Gulmohar': return 'text-red-600 bg-red-50 border-red-200';
        default: return 'text-slate-600 bg-slate-50';
    }
  };

  if (currentPage === 'teachers') {
      const studentProfile = getStudentProfile();
      const allUsers = getStoredUsers();

      // Filter teachers: Must match Role, School, and Class.
      const myTeachers = allUsers.filter(u => 
          u.role === UserRole.TEACHER && 
          u.schoolName === user.schoolName && // Ensure same school
          (u.assignedClass === studentProfile?.className)
      );

      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Teachers</h1>
                 <p className="text-slate-500">Faculty directory for Class {studentProfile?.className || 'N/A'} at {user.schoolName}</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {myTeachers.length === 0 ? (
                      <div className="col-span-full p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                           <UserIcon size={48} className="mx-auto mb-4 opacity-20" />
                           <p>No specific class teachers found for your school.</p>
                      </div>
                  ) : (
                      myTeachers.map(teacher => (
                          <div key={teacher.uid} className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden hover:shadow-md transition-shadow">
                              <div className="p-6 flex flex-col items-center text-center border-b border-slate-50">
                                  <img 
                                      src={teacher.avatarUrl} 
                                      alt={teacher.name} 
                                      className="w-20 h-20 rounded-full bg-slate-100 object-cover mb-4 border-4 border-white shadow-sm"
                                  />
                                  <h3 className="font-bold text-lg text-slate-800">{teacher.name}</h3>
                                  <p className="text-blue-600 font-medium text-sm">{teacher.assignedSubject || 'Teacher'}</p>
                                  <p className="text-slate-400 text-xs mt-1">{teacher.designation}</p>
                              </div>
                              <div className="p-4 bg-slate-50 space-y-3">
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Mail size={16} />
                                      </div>
                                      <div className="overflow-hidden">
                                          <p className="text-xs text-slate-500 font-bold uppercase">Email</p>
                                          <p className="text-slate-700 truncate" title={teacher.email || 'N/A'}>
                                              {teacher.email || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Phone size={16} />
                                      </div>
                                      <div>
                                          <p className="text-xs text-slate-500 font-bold uppercase">Contact</p>
                                          <p className="text-slate-700">
                                              {teacher.contactNumber || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'profile') {
    const studentProfile = getStudentProfile();

    if (!studentProfile) {
        return (
            <div className="p-8 text-center bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="text-slate-400 mb-2">
                    <UserIcon size={48} className="mx-auto opacity-50" />
                </div>
                <h3 className="text-lg font-bold text-slate-700">Profile Not Found</h3>
                <p className="text-slate-500">
                    Detailed information is not available. Please ask your class teacher to update your student record.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
             <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                {/* Header Section */}
                <div className="bg-slate-50 p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 font-mono text-sm">
                            <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-slate-700 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
                            </span>
                            {studentProfile.studentPost && (
                                <span className="px-3 py-1 bg-purple-100 border border-purple-200 rounded-full text-purple-700 flex items-center gap-1 font-semibold">
                                    <Shield size={14} /> {studentProfile.studentPost}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {/* Details Grid */}
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">

                    {/* Academic Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Academic Information</h3>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Class</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.className}</p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Roll Number</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.rollNumber}</p>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">House Team</label>
                                <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(studentProfile.house)}`}>
                                    <Flag size={18} />
                                    {studentProfile.house || 'No House Assigned'}
                                </div>
                            </div>
                            {user.schoolName && (
                                <div className="col-span-2">
                                    <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School</label>
                                    <p className="text-lg font-medium text-slate-800">{user.schoolName}</p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age & Gender</label>
                                <p className="text-lg font-medium text-slate-800">
                                    {studentProfile.age ? `${studentProfile.age} Years Old` : <span className="text-slate-400 italic">Not set</span>}
                                    <span className="mx-2 text-slate-300">|</span>
                                    {studentProfile.gender || 'Not set'}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Date of Birth</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Calendar size={18} className="text-slate-400" />
                                    {studentProfile.dob ? new Date(studentProfile.dob).toLocaleDateString(undefined, {
                                        year: 'numeric',
                                        month: 'long',
                                        day: 'numeric'
                                    }) : <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-purple-100 text-purple-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Mother's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.motherContact || 'N/A'}</p>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">Latest updates from the school administration.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
    const studentProfile = getStudentProfile();
    const marks = studentProfile?.marks || [];

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-slate-800">Academic Transcript</h1>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Subject</th>
                            <th className="px-6 py-4">Mid-Term</th>
                            <th className="px-6 py-4">Finals</th>
                            <th className="px-6 py-4">Avg Score</th>
                            <th className="px-6 py-4">Grade</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {marks.length === 0 ? (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400">No grades available yet.</td></tr>
                        ) : (
                            marks.map((m, i) => {
                                const avg = (m.midTerm + m.final) / 2;
                                return (
                                    <tr key={i}>
                                        <td className="px-6 py-4 font-medium">{m.subject}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.midTerm}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.final}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800">{avg.toFixed(1)}</td>
                                        <td className={`px-6 py-4 font-bold ${avg >= 70 ? 'text-green-600' : 'text-red-500'}`}>
                                            {calculateGrade(avg)}
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {studentProfile && studentProfile.gradeAverage > 0 && (
                <div className="p-4 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-700 flex justify-between items-center">
                    <span>Cumulative Grade Average</span>
                    <span className="font-bold text-lg">{studentProfile.gradeAverage}%</span>
                </div>
            )}
        </div>
    )
  }

  return (
    <div className="space-y-6">
      <header className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex items-center gap-6">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-20 h-20 rounded-full border-4 border-white/30 bg-slate-700"
          />
          <div>
            <h1 className="text-3xl font-bold mb-1">Hello, {user.name}</h1>
            <p className="text-blue-100 font-mono opacity-80">{user.schoolID} • Class {user.className || 'N/A'}</p>
            {user.schoolName && <p className="text-xs bg-white/20 inline-block px-2 py-1 rounded mt-2">{user.schoolName}</p>}
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Recent Grades */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Award className="text-yellow-500" />
            Recent Grades
          </h2>
          {/* Dynamic Recent Grades */}
          <div className="space-y-4">
            {getStudentProfile()?.marks?.slice(0, 3).map((item, idx) => {
                const score = (item.midTerm + item.final) / 2;
                return (
                    <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                        <div>
                            <p className="font-semibold text-slate-700">{item.subject}</p>
                            <p className="text-xs text-slate-500">Latest Assessment</p>
                        </div>
                        <div className="text-right">
                            <span className="text-lg font-bold text-slate-800">{calculateGrade(score)}</span>
                            <p className="text-xs text-slate-500">{score}%</p>
                        </div>
                    </div>
                );
            })}
             {(!getStudentProfile()?.marks || getStudentProfile()?.marks?.length === 0) && (
                 <p className="text-sm text-slate-400 text-center py-4">No grades recorded yet.</p>
             )}
          </div>
        </div>

        {/* Attendance Summary */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Clock className="text-blue-500" />
            Attendance Overview
          </h2>
          <div className="flex items-center justify-center py-6">
             <div className="relative h-32 w-32 rounded-full border-8 border-slate-100 flex items-center justify-center">
                <div className="absolute inset-0 border-8 border-blue-600 rounded-full border-t-transparent rotate-[-45deg]" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0 100%)' }}></div>
                <div className="text-center">
                    <span className="text-2xl font-bold text-slate-800">100%</span>
                    <p className="text-xs text-slate-400">Present</p>
                </div>
             </div>
          </div>
        </div>

        {/* Assignments */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 md:col-span-2">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Book className="text-purple-500" />
            Active Assignments
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-purple-100 text-purple-700 text-xs px-2 py-1 rounded">History</span>
                    <span className="text-xs text-slate-400">Due Tomorrow</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">World War II Essay</h3>
                <p className="text-sm text-slate-500 mt-1">Submit PDF via portal.</p>
            </div>
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded">Science</span>
                    <span className="text-xs text-slate-400">Due Friday</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">Lab Report: Chemistry</h3>
                <p className="text-sm text-slate-500 mt-1">Complete section 1-4.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;

export enum UserRole {
  STUDENT = 'student',
  TEACHER = 'teacher',
  PRINCIPAL = 'principal',
  SUPREME_ADMIN = 'supreme_admin'
}

export type HouseTeam = 'Palash' | 'Amaltash' | 'Devdar' | 'Gulmohar' | '';

export interface School {
  id: string;
  name: string;
}

export interface User {
  uid: string;
  schoolID: string;
  name: string;
  role: UserRole;
  email?: string; 
  contactNumber?: string; // New: Contact number for Teachers/Staff
  avatarUrl?: string;
  className?: string; 
  password?: string; 
  assignedClass?: string; 
  assignedSubject?: string; 
  gender?: string; 
  dob?: string;
  designation?: string; 
  house?: HouseTeam;
  schoolName?: string; // New: Assigned School
}

export interface MarkEntry {
  subject: string;
  midTerm: number;
  final: number;
}

export interface StudentRecord {
  id: string;
  name: string;
  schoolID: string;
  rollNumber: number;
  attendanceToday: boolean | null; 
  gradeAverage: number;
  className: string;
  age?: number;
  dob?: string;
  gender?: string; 
  email?: string;
  fatherContact?: string;
  motherContact?: string;
  marks?: MarkEntry[];
  house?: HouseTeam; 
  studentPost?: string;
  schoolName?: string; // New: Assigned School
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  audience: 'all' | 'student' | 'teacher';
  author: string;
  schoolName?: string; // New: If undefined/null, it is visible to ALL schools (Global)
}

export interface AttendanceStat {
  day: string;
  present: number;
  absent: number;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

export interface ERPDatabase {
  users: User[];
  students: StudentRecord[];
  announcements: Announcement[];
  schools: School[];
}

export interface CloudConfig {
  clientId: string;
  enabled: boolean;
}

import React, { useState, useEffect } from 'react';
import { User, UserRole, StudentRecord, HouseTeam, Announcement, School as SchoolType } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredStudents, updateStudent, addStudent, removeStudent, getStoredAnnouncements, addAnnouncement, deleteAnnouncement, getStoredSchools, addSchool, removeSchool } from '../services/storage';
import { Shield, Plus, School, Trash2, Pencil, Users, GraduationCap, Filter, AlertCircle, Megaphone, Send, UserCog, Building2, Globe } from 'lucide-react';
import { CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals' | 'teachers' | 'students' | 'announcements' | 'schools'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [schools, setSchools] = useState<SchoolType[]>([]);

  const [showAddModal, setShowAddModal] = useState(false);
  const [showAnnModal, setShowAnnModal] = useState(false);
  const [selectedClass, setSelectedClass] = useState<string>('All');

  // Generic Form State (Used for Principals, Teachers, Students)
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingStudent, setEditingStudent] = useState<StudentRecord | null>(null); // For extra student fields

  // Error State
  const [formError, setFormError] = useState('');

  // Form Fields
  const [formName, setFormName] = useState('');
  const [formID, setFormID] = useState('');
  const [formPassword, setFormPassword] = useState('');

  // School Assignment State
  const [formSchool, setFormSchool] = useState(''); 
  const [formPrincipalId, setFormPrincipalId] = useState(''); // For assigning teacher to principal

  // New School Form State
  const [newSchoolName, setNewSchoolName] = useState('');

  // Class Split State
  const [formGrade, setFormGrade] = useState('');
  const [formSection, setFormSection] = useState('');

  const [formSubject, setFormSubject] = useState('');
  const [formDesignation, setFormDesignation] = useState('');
  const [formHouse, setFormHouse] = useState<HouseTeam>('');
  const [formPost, setFormPost] = useState('');

  // Extended Fields (Teachers & Students)
  const [formEmail, setFormEmail] = useState('');
  const [formContact, setFormContact] = useState(''); // Teachers contact

  // Student Specific Extended Fields
  const [formDob, setFormDob] = useState('');
  const [formAge, setFormAge] = useState('');
  const [formGender, setFormGender] = useState('Male');
  const [formFatherContact, setFormFatherContact] = useState('');
  const [formMotherContact, setFormMotherContact] = useState('');

  // Announcement Form State
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [annAudience, setAnnAudience] = useState<'all' | 'student' | 'teacher'>('all');
  const [annSchool, setAnnSchool] = useState(''); // Empty means "All Schools"
  const [annSpoofType, setAnnSpoofType] = useState<'admin' | 'impersonate' | 'custom'>('admin');
  const [annImpersonateId, setAnnImpersonateId] = useState('');
  const [annCustomName, setAnnCustomName] = useState('');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setUsers(getStoredUsers());
    setStudents(getStoredStudents());
    setAnnouncements(getStoredAnnouncements());
    setSchools(getStoredSchools());
  };

  // Helper to parse "Grade-Section" string
  const parseClassString = (classStr: string) => {
    if (!classStr) return { grade: '', section: '' };
    // Assuming format "Grade-Section"
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        // Rejoin rest as section in case section has hyphens (though unlikely with current options)
        return { grade: parts[0], section: parts.slice(1).join('-') };
    }
    return { grade: classStr, section: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setFormDob(newDob);
    setFormAge(calculateAge(newDob));
  };

  // --- MODAL HANDLERS ---

  const openPrincipalModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
        setFormSchool(user.schoolName || '');
    }
    setShowAddModal(true);
  };

  const openTeacherModal = (user?: User) => {
    resetForm();
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');

        // When editing, we show the school, but maybe not the principal selector if already assigned
        setFormSchool(user.schoolName || '');

        const { grade, section } = parseClassString(user.assignedClass || '');
        setFormGrade(grade);
        setFormSection(section);

        setFormSubject(user.assignedSubject || '');
        setFormDesignation(user.designation || '');
        setFormHouse(user.house || '');
        setFormEmail(user.email || '');
        setFormContact(user.contactNumber || '');
    }
    setShowAddModal(true);
  };

  const openStudentModal = (studentRec?: StudentRecord) => {
    resetForm();
    if (studentRec) {
        setEditingStudent(studentRec);
        // Find associated user for password/login info
        const linkedUser = users.find(u => u.schoolID === studentRec.schoolID);
        setEditingUser(linkedUser || null);

        setFormName(studentRec.name);
        setFormID(studentRec.schoolID);
        setFormPassword(linkedUser?.password || '');
        setFormSchool(studentRec.schoolName || '');

        const { grade, section } = parseClassString(studentRec.className);
        setFormGrade(grade);
        setFormSection(section);

        setFormHouse(studentRec.house || '');
        setFormPost(studentRec.studentPost || '');

        // Extended Student Fields
        setFormDob(studentRec.dob || '');
        setFormAge(studentRec.age?.toString() || '');
        setFormGender(studentRec.gender || 'Male');
        setFormEmail(studentRec.email || '');
        setFormFatherContact(studentRec.fatherContact || '');
        setFormMotherContact(studentRec.motherContact || '');
    } else {
        // Defaults for new student
        setFormGender('Male');
    }
    setShowAddModal(true);
  };

  const openAnnouncementModal = () => {
      setAnnTitle('');
      setAnnContent('');
      setAnnAudience('all');
      setAnnSchool(''); // Default to All Schools
      setAnnSpoofType('admin');
      setAnnImpersonateId('');
      setAnnCustomName('');
      setShowAnnModal(true);
  };

  const resetForm = () => {
    setEditingUser(null);
    setEditingStudent(null);
    setFormError('');
    setFormName('');
    setFormID('');
    setFormPassword('');
    setFormGrade('');
    setFormSection('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
    setFormSchool('');
    setFormPrincipalId('');

    // Student Extra
    setFormDob('');
    setFormAge('');
    setFormGender('Male');
    setFormFatherContact('');
    setFormMotherContact('');
  };

  // --- SAVE HANDLERS ---

  const handleAddSchool = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newSchoolName.trim()) return;

      addSchool(newSchoolName);
      setNewSchoolName('');
      refreshData();
  };

  const handleDeleteSchool = (id: string, name: string) => {
      if (window.confirm(`Delete school "${name}"? Users assigned to this school will retain the text value but may need reassignment.`)) {
          removeSchool(id);
          refreshData();
      }
  };

  const handleSavePrincipal = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!formSchool) {
        setFormError("Please assign a School to the Principal.");
        return;
    }

    // Check Duplicate ID
    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingUser) {
        const updated: User = { 
            ...editingUser, 
            name: formName, 
            schoolID: formID, 
            password: formPassword,
            schoolName: formSchool 
        };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.PRINCIPAL,
            schoolName: formSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=3b82f6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    // If new teacher, enforce principal assignment which dictates school
    let derivedSchool = formSchool;
    if (!editingUser) {
        if (!formPrincipalId) {
            setFormError("Please assign the teacher to a Principal.");
            return;
        }
        const assignedPrincipal = users.find(u => u.uid === formPrincipalId);
        if (assignedPrincipal && assignedPrincipal.schoolName) {
            derivedSchool = assignedPrincipal.schoolName;
        } else {
            setFormError("Selected Principal does not have a valid School assigned.");
            return;
        }
    }

    if (!formGrade || !formSection) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${formGrade}-${formSection}`;

    // Validations
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formEmail && !emailRegex.test(formEmail)) {
        setFormError("Invalid email format. Please enter a valid email address.");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (formContact && !phoneRegex.test(formContact)) {
        setFormError("Contact number must be exactly 10 digits.");
        return;
    }

    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingUser) {
        const updated: User = { 
            ...editingUser, 
            name: formName, 
            schoolID: formID, 
            password: formPassword,
            assignedClass: fullClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact,
            schoolName: derivedSchool // Maintain or update school
        };
        updateUser(updated);
    } else {
        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.TEACHER,
            assignedClass: fullClass,
            assignedSubject: formSubject,
            designation: formDesignation,
            house: formHouse,
            email: formEmail,
            contactNumber: formContact,
            schoolName: derivedSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=8b5cf6&color=fff`
        };
        addUser(newUser);
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!formSchool) {
        setFormError("Please assign a School to the Student.");
        return;
    }

    if (!formGrade || !formSection) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${formGrade}-${formSection}`;

    // --- VALIDATION ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formEmail && !emailRegex.test(formEmail)) {
        setFormError("Please enter a valid school email address.");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (formFatherContact && !phoneRegex.test(formFatherContact)) {
        setFormError("Father's contact must be 10 digits.");
        return;
    }
    if (formMotherContact && !phoneRegex.test(formMotherContact)) {
        setFormError("Mother's contact must be 10 digits.");
        return;
    }

    // Check Duplicate ID
    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    if (editingStudent) {
        // --- EDIT EXISTING STUDENT ---
        const updatedRecord: StudentRecord = {
            ...editingStudent,
            name: formName,
            schoolID: formID,
            className: fullClass,
            // Roll number is preserved, but updateStudent will recalculate if name changed order
            house: formHouse,
            studentPost: formPost,
            // Extended Fields
            dob: formDob,
            age: parseInt(formAge) || 0,
            gender: formGender,
            email: formEmail,
            fatherContact: formFatherContact,
            motherContact: formMotherContact,
            schoolName: formSchool
        };
        updateStudent(updatedRecord);

        if (editingUser) {
            const updatedUser: User = {
                ...editingUser,
                name: formName,
                schoolID: formID,
                password: formPassword,
                className: fullClass,
                email: formEmail,
                gender: formGender,
                dob: formDob,
                schoolName: formSchool
            };
            updateUser(updatedUser);
        }
    } else {
        // --- CREATE NEW STUDENT ---
        const newRecord: StudentRecord = {
            id: generateId('s'),
            name: formName,
            schoolID: formID,
            rollNumber: 0, // Will be auto-assigned
            className: fullClass,
            attendanceToday: null,
            gradeAverage: 0,
            house: formHouse,
            studentPost: formPost,
            marks: [],
            // Extended Fields
            dob: formDob,
            age: parseInt(formAge) || 0,
            gender: formGender,
            email: formEmail,
            fatherContact: formFatherContact,
            motherContact: formMotherContact,
            schoolName: formSchool
        };
        addStudent(newRecord);

        const newUser: User = {
            uid: generateId('u'),
            name: formName,
            schoolID: formID,
            password: formPassword,
            role: UserRole.STUDENT,
            className: fullClass,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=f59e0b&color=fff`,
            // User Extended
            email: formEmail,
            gender: formGender,
            dob: formDob,
            schoolName: formSchool
        };
        addUser(newUser);
    }

    refreshData();
    setShowAddModal(false);
  };

  const handlePostAnnouncement = (e: React.FormEvent) => {
      e.preventDefault();

      // DETERMINE AUTHOR NAME (Identity Spoofing)
      let authorName = 'System Administrator';
      if (annSpoofType === 'impersonate' && annImpersonateId) {
          const userToImpersonate = users.find(u => u.uid === annImpersonateId);
