          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold text-slate-800">Weekly Attendance Trends</h3>
          </div>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={WEEKLY_ATTENDANCE}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} />
                <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                <Bar dataKey="present" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar dataKey="absent" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Calendar / Events */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4">Upcoming Events</h3>
          <div className="space-y-4">
            {[
              { title: "Staff Meeting", time: "10:00 AM", type: "Academic" },
              { title: "Parent-Teacher Conf", time: "2:00 PM", type: "General" },
            ].map((event, idx) => (
              <div key={idx} className="flex items-start gap-3 pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                <div className="p-2 bg-slate-50 rounded-lg">
                  <Calendar className="text-slate-400 h-5 w-5" />
                </div>
                <div>
                  <h4 className="text-sm font-semibold text-slate-700">{event.title}</h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs text-slate-500">{event.time}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrincipalDashboard;

import React, { useState, useEffect } from 'react';
import { StudentRecord, User, UserRole, MarkEntry, Announcement, HouseTeam } from '../types';
import { getStoredStudents, addStudent, updateStudent, generateId, getStoredUsers, addUser, updateUser, getStoredAnnouncements, saveAllStudents, removeStudent, removeUser } from '../services/storage';
import { CheckSquare, Square, Save, UserPlus, Pencil, GraduationCap, Plus, Trash2, Megaphone, SortAsc, Calendar, Shield, Flag, User as UserIcon, AlertCircle, Eye, EyeOff, Lock, Globe, School } from 'lucide-react';
import { CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';

interface Props {
  currentPage?: string;
  currentUser: User;
}

const TeacherDashboard: React.FC<Props> = ({ currentPage = 'dashboard', currentUser }) => {
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [hasChanges, setHasChanges] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  // Profile Edit State
  const [editHouseMode, setEditHouseMode] = useState(false);
  const [selectedHouse, setSelectedHouse] = useState<HouseTeam>(currentUser.house || '');

  // Form Error State
  const [formError, setFormError] = useState('');

  // Student Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('Male'); 
  const [schoolID, setSchoolID] = useState('');
  const [password, setPassword] = useState(''); 

  // Split Class State
  const [grade, setGrade] = useState('');
  const [section, setSection] = useState('');

  const [email, setEmail] = useState('');
  const [fatherContact, setFatherContact] = useState('');
  const [motherContact, setMotherContact] = useState('');
  const [house, setHouse] = useState<HouseTeam>('');
  const [studentPost, setStudentPost] = useState('');

  // Marks Form State
  const [showMarksModal, setShowMarksModal] = useState(false);
  const [currentMarksStudent, setCurrentMarksStudent] = useState<StudentRecord | null>(null);
  const [marksList, setMarksList] = useState<MarkEntry[]>([]);
  const [newSubject, setNewSubject] = useState('');
  const [newMidTerm, setNewMidTerm] = useState('');
  const [newFinal, setNewFinal] = useState('');

  useEffect(() => {
    // Load students and sort by roll number initially for display consistency
    const loadedStudents = getStoredStudents();

    // FILTER: Only show students in the Teacher's School
    const schoolStudents = loadedStudents.filter(s => s.schoolName === currentUser.schoolName);

    const sortedStudents = schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber);
    setStudents(sortedStudents);

    setUsers(getStoredUsers());

    // Fetch and filter announcements
    const allAnn = getStoredAnnouncements();
    const relevantAnn = allAnn.filter(a => 
        // Audience filter
        (a.audience === 'all' || a.audience === 'teacher') && 
        // School Filter: Global (no schoolName) OR Matches User's School
        (!a.schoolName || a.schoolName === currentUser.schoolName)
    );
    setAnnouncements(relevantAnn);
  }, [currentUser]);

  // Helper logic for class splitting
  const parseClassString = (classStr: string) => {
    if (!classStr) return { pGrade: '', pSection: '' };
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        return { pGrade: parts[0], pSection: parts.slice(1).join('-') };
    }
    return { pGrade: classStr, pSection: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setDob(newDob);
    const calculatedAge = calculateAge(newDob);
    setAge(calculatedAge);
  };

  const handleToggleAttendance = (id: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, attendanceToday: s.attendanceToday === false ? true : false }; 
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllPresent = () => {
    setStudents(prev => prev.map(s => ({ ...s, attendanceToday: true })));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    students.forEach(s => updateStudent(s));
    setHasChanges(false);
    alert("Attendance saved to database!");
  };

  const updateOwnHouse = () => {
      const updatedUser = { ...currentUser, house: selectedHouse };
      updateUser(updatedUser);
      setEditHouseMode(false);
      alert("House updated successfully. Please re-login to see changes in sidebar.");
  };

  // --- STUDENT MODAL LOGIC ---

  const openAddModal = () => {
    if (!currentUser.schoolName) {
        alert("Error: You are not assigned to a school. Cannot add students.");
        return;
    }
    setEditingId(null);
    setFormError('');
    setName('');
    setAge('');
    setDob('');
    setGender('Male');
    setSchoolID('');
    setPassword('');

    // Default class logic if user has a class assigned, parse it, else defaults
    if (currentUser.assignedClass) {
        const { pGrade, pSection } = parseClassString(currentUser.assignedClass);
        setGrade(pGrade);
        setSection(pSection);
    } else {
        setGrade('10th');
        setSection('A');
    }

    setEmail('');
    setFatherContact('');
    setMotherContact('');
    setHouse('');
    setStudentPost('');
    setShowModal(true);
  };

  const openEditModal = (student: StudentRecord) => {
    if (student.className !== currentUser.assignedClass) {
        alert(`You can only edit students in your assigned class (${currentUser.assignedClass || 'None'}).`);
        return;
    }

    setEditingId(student.id);
    setFormError('');
    const userLogin = users.find(u => u.schoolID === student.schoolID);

    setName(student.name);
    setAge(student.age?.toString() || '');
    setDob(student.dob || '');
    setGender(student.gender || 'Male');
    setSchoolID(student.schoolID);
    setPassword(userLogin?.password || '');

    const { pGrade, pSection } = parseClassString(student.className);
    setGrade(pGrade);
    setSection(pSection);

    setEmail(student.email || '');
    setFatherContact(student.fatherContact || '');
    setMotherContact(student.motherContact || '');
    setHouse(student.house || '');
    setStudentPost(student.studentPost || '');
    setShowModal(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!grade || !section) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${grade}-${section}`;

    // --- VALIDATION START ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email && !emailRegex.test(email)) {
        setFormError("Please enter a valid school email address (e.g., student@school.edu).");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (fatherContact && !phoneRegex.test(fatherContact)) {
        setFormError("Father's contact number must be exactly 10 digits.");
        return;
    }
    if (motherContact && !phoneRegex.test(motherContact)) {
        setFormError("Mother's contact number must be exactly 10 digits.");
        return;
    }

    // Duplicate ID Check
    const isDuplicate = users.some(u => {
        // If we are editing, we exclude the user associated with the *current* student record (by ID)
        if (editingId) {
             const originalStudent = students.find(s => s.id === editingId);
             if (originalStudent && u.schoolID === originalStudent.schoolID) {
                 return false; // This is the user's own ID
             }
        }
        return u.schoolID === schoolID;
    });

    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }
    // --- VALIDATION END ---

    let updatedList = [...getStoredStudents()];

    if (editingId) {
      // Update existing
      const existingIndex = updatedList.findIndex(s => s.id === editingId);
      if (existingIndex === -1) return;

      const existingStudent = updatedList[existingIndex];

      const updatedRecord: StudentRecord = {
        ...existingStudent,
        name,
        schoolID,
        className: fullClass,
        age: parseInt(age),
        dob,
        gender,
        email,
        fatherContact,
        motherContact,
        house,
        studentPost,
        // Ensure School matches teacher
        schoolName: currentUser.schoolName
      };

      // Update via storage service which handles sorting
      updateStudent(updatedRecord);

      // Update associated User account
      const associatedUser = users.find(u => u.schoolID === existingStudent.schoolID);
      if (associatedUser) {
        const updatedUser: User = {
          ...associatedUser,
          name,
          schoolID,
          password,
          className: fullClass,
          gender,
          dob,
          email: email,
          schoolName: currentUser.schoolName
        };
        updateUser(updatedUser);
      }

      alert(`Student ${name} updated successfully.`);

    } else {
      // Create new
      const newRecord: StudentRecord = {
        id: generateId('s'),
        name,
        schoolID,
        rollNumber: 0, // Placeholder, will be auto-assigned
        attendanceToday: null,
        gradeAverage: 0,
        className: fullClass,
        age: parseInt(age),
        dob,
        gender,
        email,
        fatherContact,
        motherContact,
        marks: [],
        house,
        studentPost,
        // Ensure School matches teacher
        schoolName: currentUser.schoolName
      };

      // Add via storage service which handles sorting
      addStudent(newRecord);

      const newUser: User = {
        uid: generateId('u'),
        name,
        schoolID,
        role: UserRole.STUDENT,
        className: fullClass,
        password,
        gender,
        dob,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f59e0b&color=fff`,
        schoolName: currentUser.schoolName
      };

      addUser(newUser);
      alert(`Student Added! Login ID: ${schoolID}, Password: ${password}`);
    }

    // Refresh Local State (Filtered by school)
    const freshStudents = getStoredStudents();
    const schoolStudents = freshStudents.filter(s => s.schoolName === currentUser.schoolName);
    setStudents(schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber));

    setUsers(getStoredUsers());
    setShowModal(false);
  };

  const handleDeleteStudent = (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (!editingId) return;

      if (window.confirm("Are you sure you want to remove this student? This will delete all their data including grades.")) {
          // Find student to get SchoolID for user deletion
          const freshStudents = getStoredStudents();
          const student = freshStudents.find(s => s.id === editingId);

          if (student) {
              removeStudent(student.id);

              const freshUsers = getStoredUsers();
              const user = freshUsers.find(u => u.schoolID === student.schoolID);
              if (user) removeUser(user.uid);
          }

          // Refresh local state
          const updatedFresh = getStoredStudents();
          const schoolStudents = updatedFresh.filter(s => s.schoolName === currentUser.schoolName);
          setStudents(schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber));

          setUsers(getStoredUsers());
          setShowModal(false);
      }
  };

  // --- MARKS LOGIC ---

  const openMarksModal = (student: StudentRecord) => {
    if (student.className !== currentUser.assignedClass) {
        alert(`You can only manage marks for students in your assigned class (${currentUser.assignedClass || 'None'}).`);
        return;
    }
    setCurrentMarksStudent(student);
    setMarksList(student.marks || []);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
    setShowMarksModal(true);
  };

  const handleAddMark = () => {
    if (!newSubject || !newMidTerm || !newFinal) {
        alert("Please fill all fields.");
        return;
    }
    const newEntry: MarkEntry = {
        subject: newSubject,
        midTerm: parseFloat(newMidTerm),
        final: parseFloat(newFinal)
    };
    setMarksList([...marksList, newEntry]);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
  };

  const handleRemoveMark = (index: number) => {
    const updated = [...marksList];
    updated.splice(index, 1);
    setMarksList(updated);
  };

  const saveMarks = () => {
    if (!currentMarksStudent) return;

    // Calculate new average
    let totalScore = 0;
    let count = 0;
    marksList.forEach(m => {
        totalScore += (m.midTerm + m.final) / 2;
        count++;
    });
    const newAverage = count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0;

    const updatedStudent: StudentRecord = {
        ...currentMarksStudent,
        marks: marksList,
        gradeAverage: newAverage
    };

    updateStudent(updatedStudent);
    // Refresh list from storage and sort
    const freshStudents = getStoredStudents();
    const schoolStudents = freshStudents.filter(s => s.schoolName === currentUser.schoolName);
    setStudents(schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber));

    setShowMarksModal(false);
    alert(`Marks updated for ${currentMarksStudent.name}`);
  };

  const getHouseColor = (house?: HouseTeam) => {
    switch(house) {
        case 'Palash': return 'bg-green-100 text-green-700 border-green-200';
        case 'Amaltash': return 'bg-blue-100 text-blue-700 border-blue-200';
        case 'Devdar': return 'bg-yellow-100 text-yellow-700 border-yellow-200';
        case 'Gulmohar': return 'bg-red-100 text-red-700 border-red-200';
        default: return 'bg-slate-50 text-slate-500 border-slate-100';
    }
  };

  // --- RENDERING ---

  if (currentPage === 'profile') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
                 <p className="text-slate-500">Manage your personal details and settings.</p>
                 {currentUser.schoolName && (
                    <div className="mt-2 inline-flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 text-sm font-semibold text-blue-600">
                        <UserIcon size={14} /> {currentUser.schoolName}
                    </div>
                 )}
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden max-w-2xl">
                 <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6 bg-slate-50">
                    <img 
                        src={currentUser.avatarUrl} 
                        alt={currentUser.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left">
                        <h2 className="text-2xl font-bold text-slate-900">{currentUser.name}</h2>
                        <p className="text-slate-500 font-mono text-sm">{currentUser.schoolID} • {currentUser.designation || 'Teacher'}</p>
                    </div>
                 </div>

                 <div className="p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div>
                             <label className="block text-xs text-slate-400 font-bold uppercase mb-1">Class Assigned</label>
                             <p className="text-lg font-medium text-slate-800">{currentUser.assignedClass || 'N/A'}</p>
                         </div>
                         <div>
                             <label className="block text-xs text-slate-400 font-bold uppercase mb-1">Subject</label>
                             <p className="text-lg font-medium text-slate-800">{currentUser.assignedSubject || 'N/A'}</p>
                         </div>
                    </div>

                    <div className="pt-6 border-t border-slate-100">
                         <div className="flex justify-between items-center mb-4">
                             <h3 className="text-sm font-bold text-slate-700 uppercase flex items-center gap-2">
                                <Flag size={16} /> House Team
                             </h3>
                             {!editHouseMode && (
                                 <button 
                                    onClick={() => setEditHouseMode(true)}
                                    className="text-xs text-blue-600 hover:text-blue-800 font-medium"
                                 >
                                     Change House
                                 </button>
                             )}
                         </div>

                         {editHouseMode ? (
                             <div className="flex items-center gap-3">
                                 <select 
                                    className="flex-1 px-4 py-2 border rounded-lg focus:outline-none focus:border-blue-500"
                                    value={selectedHouse}
                                    onChange={(e) => setSelectedHouse(e.target.value as HouseTeam)}
                                 >
                                    <option value="">Select House</option>
                                    <option value="Palash">Palash (Green)</option>
                                    <option value="Amaltash">Amaltash (Blue)</option>
                                    <option value="Devdar">Devdar (Yellow)</option>
                                    <option value="Gulmohar">Gulmohar (Red)</option>
                                 </select>
                                 <button onClick={updateOwnHouse} className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">Save</button>
                                 <button onClick={() => setEditHouseMode(false)} className="px-4 py-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300">Cancel</button>
                             </div>
                         ) : (
                             <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(currentUser.house as HouseTeam)}`}>
                                 {currentUser.house || 'No House Assigned'}
                             </div>
                         )}
                    </div>
                 </div>
              </div>
          </div>
      );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">School-wide announcements and teacher updates.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <div className="flex items-center gap-2 mt-1">
                                        <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                        {!ann.schoolName && (
                                            <span className="flex items-center gap-1 text-[10px] uppercase font-bold px-2 py-0.5 bg-purple-50 text-purple-600 rounded-full border border-purple-100">
                                                <Globe size={10} /> Global
                                            </span>
                                        )}
                                        {ann.schoolName && (
                                            <span className="flex items-center gap-1 text-[10px] uppercase font-bold px-2 py-0.5 bg-blue-50 text-blue-600 rounded-full border border-blue-100">
                                                <School size={10} /> {ann.schoolName}
                                            </span>
                                        )}
                                     </div>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">Student Grades</h1>
                    <p className="text-slate-500">Manage Assessments & Results</p>
                </div>
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Student Name</th>
                            <th className="px-6 py-4">Roll No</th>
                            <th className="px-6 py-4">Overall GPA</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {students.length === 0 ? (
                             <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>
                        ) : (
                            students.map(s => {
                                // Only allow managing marks for own class
                                const canEdit = s.className === currentUser.assignedClass;
                                return (
                                <tr key={s.id} className="hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium">{s.name}</td>
                                    <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                                    <td className="px-6 py-4 font-bold text-blue-600">
                                        {s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        {canEdit ? (
                                            <button 
                                                onClick={() => openMarksModal(s)}
                                                className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 transition-colors flex items-center gap-2 ml-auto"
                                            >
                                                <GraduationCap size={16} /> Manage Marks
                                            </button>
                                        ) : (
                                            <span className="text-xs text-slate-400 italic">View Only</span>
                                        )}
                                    </td>
                                </tr>
                            )})
                        )}
                    </tbody>
                </table>
              </div>

              {/* Marks Modal */}
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                    <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                            <div>
                                <h2 className="text-xl font-bold text-slate-800">Manage Marks</h2>
                                <p className="text-slate-500 text-sm">Student: {currentMarksStudent.name} (Roll: {currentMarksStudent.rollNumber})</p>
                            </div>
                            <button onClick={() => setShowMarksModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
                        </div>

                        <div className="space-y-6">
                            {/* Input Row */}
                            <div className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg border border-slate-200">
                                <div className="flex-1">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Subject</label>
                                    <input 
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="e.g. Mathematics"
                                        value={newSubject}
                                        onChange={e => setNewSubject(e.target.value)}
                                    />
                                </div>
                                <div className="w-24">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Mid-Term</label>
                                    <input 
                                        type="number"
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="0-100"
                                        value={newMidTerm}
                                        onChange={e => setNewMidTerm(e.target.value)}
                                    />
                                </div>
                                <div className="w-24">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Finals</label>
                                    <input 
                                        type="number"
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="0-100"
                                        value={newFinal}
                                        onChange={e => setNewFinal(e.target.value)}
                                    />
                                </div>
                                <button 
                                    onClick={handleAddMark}
                                    className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 flex items-center gap-1 h-[38px]"
                                >
                                    <Plus size={16} /> Add
                                </button>
                            </div>

                            {/* List */}
                            <table className="w-full text-left border border-slate-200 rounded-lg overflow-hidden">
                                <thead className="bg-slate-100 text-slate-600 text-xs uppercase">
                                    <tr>
                                        <th className="px-4 py-3">Subject</th>
                                        <th className="px-4 py-3">Mid-Term</th>
                                        <th className="px-4 py-3">Finals</th>
                                        <th className="px-4 py-3">Average</th>
                                        <th className="px-4 py-3 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {marksList.length === 0 ? (
                                        <tr><td colSpan={5} className="p-6 text-center text-slate-400 text-sm">No marks added yet.</td></tr>
                                    ) : (
                                        marksList.map((m, idx) => (
                                            <tr key={idx}>
                                                <td className="px-4 py-3 font-medium">{m.subject}</td>
                                                <td className="px-4 py-3 text-slate-600">{m.midTerm}</td>
                                                <td className="px-4 py-3 text-slate-600">{m.final}</td>
                                                <td className="px-4 py-3 font-bold text-blue-600">{((m.midTerm + m.final) / 2).toFixed(1)}</td>
                                                <td className="px-4 py-3 text-right">
                                                    <button onClick={() => handleRemoveMark(idx)} className="text-red-500 hover:text-red-700">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>

                        <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100">
                            <button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg">Cancel</button>
                            <button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700">Save Grades</button>
                        </div>
                    </div>
                  </div>
              )}
          </div>
      );
  }

  // DEFAULT DASHBOARD
  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Class {currentUser.assignedClass || 'Unassigned'}</h1>
          <p className="text-slate-500">Daily Attendance & Roster</p>
          {currentUser.schoolName && (
             <div className="mt-2 inline-flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 text-sm font-semibold text-blue-600">
                <UserIcon size={14} /> {currentUser.schoolName}
             </div>
          )}
        </div>

        <div className="flex items-center gap-3">
           <button 
            onClick={markAllPresent}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 font-medium rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
          >
            <CheckSquare size={18} />
            Mark All Present
          </button>

          <button 
            onClick={saveAttendance}
            disabled={!hasChanges}
            className={`flex items-center gap-2 px-6 py-2 font-medium rounded-lg transition-all shadow-sm ${
              hasChanges 
              ? 'bg-blue-600 text-white hover:bg-blue-700' 
              : 'bg-slate-200 text-slate-400 cursor-not-allowed'
            }`}
          >
            <Save size={18} />
            Save Records
          </button>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        {/* List */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
              <tr>
                <th className="px-6 py-4">Student Name</th>
                <th className="px-6 py-4">Roll No</th>
                <th className="px-6 py-4">ID</th>
                <th className="px-6 py-4">Class</th>
                <th className="px-6 py-4">House / Post</th>
                <th className="px-6 py-4">Parents Contact</th>
                <th className="px-6 py-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.length === 0 ? (
                  <tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">No students found. Go to "My Classes" to add them.</td></tr>
              ) : (
                students.map((student) => {
                    const isPresent = student.attendanceToday === true;
                    const isAbsent = student.attendanceToday === false;
                    const canEdit = student.className === currentUser.assignedClass;

                    return (
                    <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                        <div className="font-medium text-slate-900">{student.name}</div>
                        </td>
                        <td className="px-6 py-4 font-mono text-sm text-slate-500">
                        {student.rollNumber}
                        </td>
                        <td className="px-6 py-4 font-mono text-sm text-slate-500">
                        {student.schoolID}
                        </td>
                        <td className="px-6 py-4 text-sm text-slate-500">{student.className}</td>
                        <td className="px-6 py-4">
                            <div className="flex flex-col gap-1 items-start">
                                {student.house && (
                                    <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded-full border ${getHouseColor(student.house)}`}>
                                        {student.house}
                                    </span>
                                )}
                                {student.studentPost && (
                                        <span className="text-xs font-semibold text-purple-600 flex items-center gap-1">
                                        <Shield size={10} /> {student.studentPost}
                                        </span>
                                )}
                            </div>
                        </td>
                        <td className="px-6 py-4 text-sm text-slate-500">
                            {student.fatherContact ? `F: ${student.fatherContact}` : ''}
                            {student.fatherContact && student.motherContact ? <br/> : ''}
                            {student.motherContact ? `M: ${student.motherContact}` : ''}
                        </td>
                        <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                            {canEdit ? (
                                <>
                                    <button 
                                        onClick={() => handleToggleAttendance(student.id)}
                                        className={`p-2 rounded-lg transition-colors ${
                                            isPresent 
                                            ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                                            : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                        }`}
                                    >
                                        <CheckSquare size={18} />
                                    </button>
                                    <button 
                                        onClick={() => handleToggleAttendance(student.id)}
                                        className={`p-2 rounded-lg transition-colors ${
                                            isAbsent 
                                            ? 'bg-red-100 text-red-700 hover:bg-red-200' 
                                            : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                        }`}
                                    >
                                        <Square size={18} className={isAbsent ? "fill-current" : ""} />
                                    </button>
                                    <button 
                                        onClick={() => openEditModal(student)}
                                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    >
                                        <Pencil size={18} />
                                    </button>
                                </>
                            ) : (
                                <span className="text-xs text-slate-400 italic flex items-center gap-1">
                                    <Lock size={12} /> View Only
                                </span>
                            )}
                        </div>
                        </td>
                    </tr>
                    );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect } from 'react';
import { User, StudentRecord, MarkEntry, Announcement, HouseTeam, UserRole } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash, Megaphone, Calendar, Shield, Flag, Globe, School } from 'lucide-react';
import { getStoredStudents, getStoredAnnouncements, getStoredUsers } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  useEffect(() => {
     const allAnn = getStoredAnnouncements();
     const relevantAnn = allAnn.filter(a => 
         // Audience Filter
         (a.audience === 'all' || a.audience === 'student') &&
         // School Filter: Global (no schoolName) OR Matches User's School
         (!a.schoolName || a.schoolName === user.schoolName)
     );
     setAnnouncements(relevantAnn);
  }, []);

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

   const getHouseColor = (house?: HouseTeam) => {
    switch(house) {
        case 'Palash': return 'text-green-600 bg-green-50 border-green-200';
        case 'Amaltash': return 'text-blue-600 bg-blue-50 border-blue-200';
        case 'Devdar': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
        case 'Gulmohar': return 'text-red-600 bg-red-50 border-red-200';
        default: return 'text-slate-600 bg-slate-50';
    }
  };

  if (currentPage === 'teachers') {
      const studentProfile = getStudentProfile();
      const allUsers = getStoredUsers();

      // Filter teachers: Must match Role, School, and Class.
      const myTeachers = allUsers.filter(u => 
          u.role === UserRole.TEACHER && 
          u.schoolName === user.schoolName && // Ensure same school
          (u.assignedClass === studentProfile?.className)
      );

      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Teachers</h1>
                 <p className="text-slate-500">Faculty directory for Class {studentProfile?.className || 'N/A'} at {user.schoolName}</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {myTeachers.length === 0 ? (
                      <div className="col-span-full p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                           <UserIcon size={48} className="mx-auto mb-4 opacity-20" />
                           <p>No specific class teachers found for your school.</p>
                      </div>
                  ) : (
                      myTeachers.map(teacher => (
                          <div key={teacher.uid} className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden hover:shadow-md transition-shadow">
                              <div className="p-6 flex flex-col items-center text-center border-b border-slate-50">
                                  <img 
                                      src={teacher.avatarUrl} 
                                      alt={teacher.name} 
                                      className="w-20 h-20 rounded-full bg-slate-100 object-cover mb-4 border-4 border-white shadow-sm"
                                  />
                                  <h3 className="font-bold text-lg text-slate-800">{teacher.name}</h3>
                                  <p className="text-blue-600 font-medium text-sm">{teacher.assignedSubject || 'Teacher'}</p>
                                  <p className="text-slate-400 text-xs mt-1">{teacher.designation}</p>
                              </div>
                              <div className="p-4 bg-slate-50 space-y-3">
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Mail size={16} />
                                      </div>
                                      <div className="overflow-hidden">
                                          <p className="text-xs text-slate-500 font-bold uppercase">Email</p>
                                          <p className="text-slate-700 truncate" title={teacher.email || 'N/A'}>
                                              {teacher.email || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Phone size={16} />
                                      </div>
                                      <div>
                                          <p className="text-xs text-slate-500 font-bold uppercase">Contact</p>
                                          <p className="text-slate-700">
                                              {teacher.contactNumber || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'profile') {
    const studentProfile = getStudentProfile();

    if (!studentProfile) {
        return (
            <div className="p-8 text-center bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="text-slate-400 mb-2">
                    <UserIcon size={48} className="mx-auto opacity-50" />
                </div>
                <h3 className="text-lg font-bold text-slate-700">Profile Not Found</h3>
                <p className="text-slate-500">
                    Detailed information is not available. Please ask your class teacher to update your student record.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
             <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                {/* Header Section */}
                <div className="bg-slate-50 p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 font-mono text-sm">
                            <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-slate-700 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
                            </span>
                            {studentProfile.studentPost && (
                                <span className="px-3 py-1 bg-purple-100 border border-purple-200 rounded-full text-purple-700 flex items-center gap-1 font-semibold">
                                    <Shield size={14} /> {studentProfile.studentPost}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {/* Details Grid */}
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">

                    {/* Academic Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Academic Information</h3>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Class</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.className}</p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Roll Number</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.rollNumber}</p>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">House Team</label>
                                <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(studentProfile.house)}`}>
                                    <Flag size={18} />
                                    {studentProfile.house || 'No House Assigned'}
                                </div>
                            </div>
                            {user.schoolName && (
                                <div className="col-span-2">
                                    <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School</label>
                                    <p className="text-lg font-medium text-slate-800">{user.schoolName}</p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age & Gender</label>
                                <p className="text-lg font-medium text-slate-800">
                                    {studentProfile.age ? `${studentProfile.age} Years Old` : <span className="text-slate-400 italic">Not set</span>}
                                    <span className="mx-2 text-slate-300">|</span>
                                    {studentProfile.gender || 'Not set'}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Date of Birth</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Calendar size={18} className="text-slate-400" />
                                    {studentProfile.dob ? new Date(studentProfile.dob).toLocaleDateString(undefined, {
                                        year: 'numeric',
                                        month: 'long',
                                        day: 'numeric'
                                    }) : <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-purple-100 text-purple-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Mother's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.motherContact || 'N/A'}</p>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">Latest updates from the school administration.</p>
