// --- Helper for Auto-Roll Number Generation ---
export const recalculateRollNumbers = (className: string): void => {
  const allStudents = getStoredStudents();
  // Filter students of this class
  const classStudents = allStudents.filter(s => s.className === className);
  const otherStudents = allStudents.filter(s => s.className !== className);

  // Sort alphabetically by name
  classStudents.sort((a, b) => a.name.localeCompare(b.name));

  // Assign roll numbers sequentially
  classStudents.forEach((s, index) => {
    s.rollNumber = index + 1;
  });

  // Save merged list
  const merged = [...otherStudents, ...classStudents];
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(merged));
};

export const getStoredUsers = (): User[] => {
  const stored = localStorage.getItem(STORAGE_KEY_USERS);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(INITIAL_USERS));
    return INITIAL_USERS;
  }
  return JSON.parse(stored);
};

export const addUser = (user: User): void => {
  const users = getStoredUsers();
  users.push(user);
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const updateUser = (updatedUser: User): void => {
  const users = getStoredUsers();
  const index = users.findIndex(u => u.uid === updatedUser.uid);
  if (index !== -1) {
    users[index] = updatedUser;
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
  }
};

export const removeUser = (uid: string): void => {
  let users = getStoredUsers();
  users = users.filter(u => u.uid !== uid);
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const getStoredStudents = (): StudentRecord[] => {
  const stored = localStorage.getItem(STORAGE_KEY_STUDENTS);
  return stored ? JSON.parse(stored) : [];
};

export const addStudent = (student: StudentRecord): void => {
  const students = getStoredStudents();
  students.push(student);
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
  // Auto-calculate roll numbers for the class
  recalculateRollNumbers(student.className);
};

export const updateStudent = (updatedStudent: StudentRecord): void => {
  const students = getStoredStudents();
  const index = students.findIndex(s => s.id === updatedStudent.id);

  if (index !== -1) {
    const oldClass = students[index].className;
    students[index] = updatedStudent;
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));

    // Recalculate for new class
    recalculateRollNumbers(updatedStudent.className);

    // If class changed, recalculate for old class to fill gaps
    if (oldClass !== updatedStudent.className) {
        recalculateRollNumbers(oldClass);
    }
  }
};

export const removeStudent = (studentId: string): void => {
    const students = getStoredStudents();
    const student = students.find(s => s.id === studentId);

    if (student) {
        const className = student.className;
        const newList = students.filter(s => s.id !== studentId);
        localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(newList));
        // Re-assign roll numbers for the class to fill the gap
        recalculateRollNumbers(className);
    }
};

export const saveAllStudents = (students: StudentRecord[]): void => {
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
};

export const getStoredAnnouncements = (): Announcement[] => {
  const stored = localStorage.getItem(STORAGE_KEY_ANNOUNCEMENTS);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY_ANNOUNCEMENTS, JSON.stringify(INITIAL_ANNOUNCEMENTS));
    return INITIAL_ANNOUNCEMENTS;
  }
  return JSON.parse(stored);
};

export const addAnnouncement = (announcement: Announcement): void => {
  const items = getStoredAnnouncements();
  items.unshift(announcement);
  localStorage.setItem(STORAGE_KEY_ANNOUNCEMENTS, JSON.stringify(items));
};

export const deleteAnnouncement = (id: string): void => {
  let items = getStoredAnnouncements();
  items = items.filter(i => i.id !== id);
  localStorage.setItem(STORAGE_KEY_ANNOUNCEMENTS, JSON.stringify(items));
};

// --- SCHOOL MANAGEMENT ---
export const getStoredSchools = (): School[] => {
  const stored = localStorage.getItem(STORAGE_KEY_SCHOOLS);
  if (!stored) {
    // Initialize with default constants if first run
    const defaults: School[] = SCHOOL_NAMES.map((name, idx) => ({
        id: `sch-init-${idx}`,
        name: name,
        config: DEFAULT_SCHOOL_CONFIG
    }));
    localStorage.setItem(STORAGE_KEY_SCHOOLS, JSON.stringify(defaults));
    return defaults;
  }
  const schools = JSON.parse(stored);
  // Migration for old data without config
  return schools.map((s: any) => ({
      ...s,
      config: s.config || DEFAULT_SCHOOL_CONFIG
  }));
};

export const addSchool = (name: string, config?: SchoolConfig): void => {
    const schools = getStoredSchools();
    const newSchool: School = {
        id: generateId('sch'),
        name: name.trim(),
        config: config || DEFAULT_SCHOOL_CONFIG
    };
    schools.push(newSchool);
    localStorage.setItem(STORAGE_KEY_SCHOOLS, JSON.stringify(schools));
};

export const updateSchool = (updatedSchool: School): void => {
    const schools = getStoredSchools();
    const index = schools.findIndex(s => s.id === updatedSchool.id);
    if (index !== -1) {
        schools[index] = updatedSchool;
        localStorage.setItem(STORAGE_KEY_SCHOOLS, JSON.stringify(schools));
    }
}

export const removeSchool = (id: string): void => {
    let schools = getStoredSchools();
    schools = schools.filter(s => s.id !== id);
    localStorage.setItem(STORAGE_KEY_SCHOOLS, JSON.stringify(schools));
};

export const getFullDatabase = (): ERPDatabase => {
  return {
    users: getStoredUsers(),
    students: getStoredStudents(),
    announcements: getStoredAnnouncements(),
    schools: getStoredSchools()
  };
};

export const restoreFullDatabase = (data: ERPDatabase): void => {
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(data.users));
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(data.students));
  localStorage.setItem(STORAGE_KEY_ANNOUNCEMENTS, JSON.stringify(data.announcements));
  if (data.schools) {
      localStorage.setItem(STORAGE_KEY_SCHOOLS, JSON.stringify(data.schools));
  }
};

export const generateId = (prefix: string): string => {
  return `${prefix}-${Math.floor(Math.random() * 10000)}`;
};

import React, { useState, useEffect } from 'react';
import { User, UserRole, StudentRecord, HouseTeam, Announcement, School as SchoolType, SchoolConfig } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredStudents, updateStudent, addStudent, removeStudent, getStoredAnnouncements, addAnnouncement, deleteAnnouncement, getStoredSchools, addSchool, removeSchool, updateSchool } from '../services/storage';
import { Shield, Plus, School, Trash2, Pencil, Users, GraduationCap, Filter, AlertCircle, Megaphone, Send, UserCog, Building2, Globe, Settings, Save } from 'lucide-react';
import { CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals' | 'teachers' | 'students' | 'announcements' | 'schools'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [schools, setSchools] = useState<SchoolType[]>([]);

  const [showAddModal, setShowAddModal] = useState(false);
  const [modalType, setModalType] = useState<'principal' | 'teacher' | 'student'>('principal');

  const [showAnnModal, setShowAnnModal] = useState(false);
  const [selectedClass, setSelectedClass] = useState<string>('All');

  // School Config Modal
  const [showSchoolModal, setShowSchoolModal] = useState(false);
  const [editingSchool, setEditingSchool] = useState<SchoolType | null>(null);
  const [scFormName, setScFormName] = useState('');
  const [scFormMaxMarks, setScFormMaxMarks] = useState('100');
  const [scFormHouses, setScFormHouses] = useState('');
  const [scFormStreams, setScFormStreams] = useState('');

  // Announcement Form State
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [annAudience, setAnnAudience] = useState<'all' | 'student' | 'teacher'>('all');
  const [annSchool, setAnnSchool] = useState('');
  const [annSpoofType, setAnnSpoofType] = useState<'admin' | 'impersonate' | 'custom'>('admin');
  const [annImpersonateId, setAnnImpersonateId] = useState('');
  const [annCustomName, setAnnCustomName] = useState('');

  // Generic Form State
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingStudent, setEditingStudent] = useState<StudentRecord | null>(null);

  // Error State
  const [formError, setFormError] = useState('');

  // Form Fields
  const [formName, setFormName] = useState('');
  const [formID, setFormID] = useState('');
  const [formPassword, setFormPassword] = useState('');
  const [formSchool, setFormSchool] = useState(''); 

  const [formGrade, setFormGrade] = useState('');
  const [formSection, setFormSection] = useState('');

  const [formSubject, setFormSubject] = useState('');
  const [formDesignation, setFormDesignation] = useState('');
  const [formHouse, setFormHouse] = useState<HouseTeam>('');
  const [formPost, setFormPost] = useState('');

  const [formEmail, setFormEmail] = useState('');
  const [formContact, setFormContact] = useState(''); 

  const [formDob, setFormDob] = useState('');
  const [formAge, setFormAge] = useState('');
  const [formGender, setFormGender] = useState('Male');
  const [formFatherContact, setFormFatherContact] = useState('');
  const [formMotherContact, setFormMotherContact] = useState('');

  // Derived State for Dropdowns
  const [currentSchoolConfig, setCurrentSchoolConfig] = useState<SchoolConfig | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  // Watch formSchool changes to update config for dropdowns
  useEffect(() => {
      if (formSchool) {
          const s = schools.find(s => s.name === formSchool);
          if (s) setCurrentSchoolConfig(s.config);
          else setCurrentSchoolConfig(null);
      } else {
          setCurrentSchoolConfig(null);
      }
  }, [formSchool, schools]);

  const refreshData = () => {
    setUsers(getStoredUsers());
    setStudents(getStoredStudents());
    setAnnouncements(getStoredAnnouncements());
    setSchools(getStoredSchools());
  };

  const parseClassString = (classStr: string) => {
    if (!classStr) return { grade: '', section: '' };
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        return { grade: parts[0], section: parts.slice(1).join('-') };
    }
    return { grade: classStr, section: '' };
  };

  const getSectionOptions = (grade: string) => {
      // If we have a specific school config and it's a senior grade, try to use streams
      if (['11th', '12th'].includes(grade)) {
          if (currentSchoolConfig && currentSchoolConfig.streams.length > 0) {
              return currentSchoolConfig.streams;
          }
          return SECTIONS_SENIOR; // Fallback
      }
      return SECTIONS_JUNIOR;
  };

  const getHouseOptions = () => {
      if (currentSchoolConfig && currentSchoolConfig.houseNames.length > 0) {
          return currentSchoolConfig.houseNames;
      }
      return ['Green', 'Blue', 'Yellow', 'Red']; // Fallback
  };

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setFormDob(newDob);
    setFormAge(calculateAge(newDob));
  };

  const openPrincipalModal = (user?: User) => {
    resetForm();
    setModalType('principal');
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
        setFormSchool(user.schoolName || '');
    }
    setShowAddModal(true);
  };

  const openTeacherModal = (user?: User) => {
    resetForm();
    setModalType('teacher');
    if (user) {
        setEditingUser(user);
        setFormName(user.name);
        setFormID(user.schoolID);
        setFormPassword(user.password || '');
        setFormSchool(user.schoolName || '');

        const { grade, section } = parseClassString(user.assignedClass || '');
        setFormGrade(grade);
        setFormSection(section);

        setFormSubject(user.assignedSubject || '');
        setFormDesignation(user.designation || '');
        setFormHouse(user.house || '');
        setFormEmail(user.email || '');
        setFormContact(user.contactNumber || '');
    }
    setShowAddModal(true);
  };

  const openStudentModal = (studentRec?: StudentRecord) => {
    resetForm();
    setModalType('student');
    if (studentRec) {
        setEditingStudent(studentRec);
        const linkedUser = users.find(u => u.schoolID === studentRec.schoolID);
        setEditingUser(linkedUser || null);

        setFormName(studentRec.name);
        setFormID(studentRec.schoolID);
        setFormPassword(linkedUser?.password || '');
        setFormSchool(studentRec.schoolName || '');

        const { grade, section } = parseClassString(studentRec.className);
        setFormGrade(grade);
        setFormSection(section);

        setFormHouse(studentRec.house || '');
        setFormPost(studentRec.studentPost || '');

        setFormDob(studentRec.dob || '');
        setFormAge(studentRec.age?.toString() || '');
        setFormGender(studentRec.gender || 'Male');
        setFormEmail(studentRec.email || '');
        setFormFatherContact(studentRec.fatherContact || '');
        setFormMotherContact(studentRec.motherContact || '');
    } else {
        setFormGender('Male');
    }
    setShowAddModal(true);
  };

  const openSchoolModal = (school?: SchoolType) => {
      setEditingSchool(school || null);
      if (school) {
          setScFormName(school.name);
          setScFormMaxMarks(school.config?.maxMarks.toString() || '100');
          setScFormHouses(school.config?.houseNames.join(', ') || 'Green, Blue, Yellow, Red');
          setScFormStreams(school.config?.streams.join(', ') || 'Science, Commerce, Humanities');
      } else {
          setScFormName('');
          setScFormMaxMarks('100');
          setScFormHouses('Green, Blue, Yellow, Red');
          setScFormStreams('Science, Commerce, Humanities');
      }
      setShowSchoolModal(true);
  };

  const openAnnouncementModal = () => {
      setAnnTitle('');
      setAnnContent('');
      setAnnAudience('all');
      setAnnSchool(''); 
      setAnnSpoofType('admin');
      setAnnImpersonateId('');
      setAnnCustomName('');
      setShowAnnModal(true);
  };

  const resetForm = () => {
    setEditingUser(null);
    setEditingStudent(null);
    setFormError('');
    setFormName('');
    setFormID('');
    setFormPassword('');
    setFormGrade('');
    setFormSection('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
    setFormSchool('');

    setFormDob('');
    setFormAge('');
    setFormGender('Male');
    setFormFatherContact('');
    setFormMotherContact('');
  };

  const handleSaveSchool = (e: React.FormEvent) => {
      e.preventDefault();
      const config: SchoolConfig = {
          maxMarks: parseInt(scFormMaxMarks) || 100,
          houseNames: scFormHouses.split(',').map(s => s.trim()).filter(s => s),
          streams: scFormStreams.split(',').map(s => s.trim()).filter(s => s)
      };

      if (editingSchool) {
          updateSchool({
              ...editingSchool,
              name: scFormName,
              config
          });
      } else {
          addSchool(scFormName, config);
      }
      refreshData();
      setShowSchoolModal(false);
  };

  const handleDeleteSchool = (id: string, name: string) => {
      if (window.confirm(`Delete school "${name}"? Users assigned to this school will retain the text value but may need reassignment.`)) {
          removeSchool(id);
          refreshData();
      }
  };

  const handleSaveUser = (e: React.FormEvent) => {
      e.preventDefault();

      if (modalType === 'principal') handleSavePrincipal(e);
      else if (modalType === 'teacher') handleSaveTeacher(e);
      else if (modalType === 'student') handleSaveStudent(e);
  }

  const handleSavePrincipal = (e: React.FormEvent) => {
    setFormError('');
    if (!formSchool) { setFormError("Please assign a School."); return; }
    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) { setFormError("School ID already exists."); return; }

    if (editingUser) {
        updateUser({ ...editingUser, name: formName, schoolID: formID, password: formPassword, schoolName: formSchool });
    } else {
        addUser({
            uid: generateId('u'), name: formName, schoolID: formID, password: formPassword,
            role: UserRole.PRINCIPAL, schoolName: formSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=3b82f6&color=fff`
        });
    }
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    setFormError('');
    if (!formSchool) { setFormError("Please assign a School."); return; }
    if (!formGrade || !formSection) { setFormError("Please select Class/Section."); return; }
    const fullClass = `${formGrade}-${formSection}`;

    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) { setFormError("School ID already exists."); return; }

    const userData: User = {
        uid: editingUser ? editingUser.uid : generateId('u'),
        name: formName, schoolID: formID, password: formPassword,
        role: UserRole.TEACHER, assignedClass: fullClass, assignedSubject: formSubject,
        designation: formDesignation, house: formHouse, email: formEmail, contactNumber: formContact,
        schoolName: formSchool,
        avatarUrl: editingUser?.avatarUrl || `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=8b5cf6&color=fff`
    };

    if (editingUser) updateUser(userData); else addUser(userData);
    refreshData();
    setShowAddModal(false);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    setFormError('');
    if (!formSchool) { setFormError("Please assign a School."); return; }
    if (!formGrade || !formSection) { setFormError("Please select Class/Section."); return; }
    const fullClass = `${formGrade}-${formSection}`;

    const isDuplicate = users.some(u => u.schoolID === formID && u.uid !== editingUser?.uid);
    if (isDuplicate) { setFormError("School ID already exists."); return; }

    if (editingStudent) {
        updateStudent({
            ...editingStudent, name: formName, schoolID: formID, className: fullClass,
            house: formHouse, studentPost: formPost, dob: formDob, age: parseInt(formAge) || 0,
            gender: formGender, email: formEmail, fatherContact: formFatherContact, motherContact: formMotherContact,
            schoolName: formSchool
        });
        if (editingUser) {
            updateUser({ ...editingUser, name: formName, schoolID: formID, password: formPassword, className: fullClass, email: formEmail, gender: formGender, dob: formDob, schoolName: formSchool });
        }
    } else {
        addStudent({
            id: generateId('s'), name: formName, schoolID: formID, rollNumber: 0, className: fullClass,
            attendanceToday: null, gradeAverage: 0, house: formHouse, studentPost: formPost, marks: [],
            dob: formDob, age: parseInt(formAge) || 0, gender: formGender, email: formEmail, fatherContact: formFatherContact, motherContact: formMotherContact,
            schoolName: formSchool
        });
        addUser({
            uid: generateId('u'), name: formName, schoolID: formID, password: formPassword,
            role: UserRole.STUDENT, className: fullClass, email: formEmail, gender: formGender, dob: formDob, schoolName: formSchool,
            avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(formName)}&background=f59e0b&color=fff`
        });
    }
    refreshData();
    setShowAddModal(false);
  };

  const handlePostAnnouncement = (e: React.FormEvent) => {
      e.preventDefault();
      let authorName = 'System Administrator';
      if (annSpoofType === 'impersonate' && annImpersonateId) {
          const userToImpersonate = users.find(u => u.uid === annImpersonateId);
          if (userToImpersonate) authorName = userToImpersonate.name;
      } else if (annSpoofType === 'custom' && annCustomName) {
          authorName = annCustomName;
      }

      addAnnouncement({
          id: generateId('ann'), title: annTitle, content: annContent,
          date: new Date().toISOString().split('T')[0], audience: annAudience,
          author: authorName, schoolName: annSchool || undefined
      });
      refreshData();
      setShowAnnModal(false);
  };

  const handleDeleteUser = (user: User) => {
      if(window.confirm(`Delete user ${user.name}?`)) {
          removeUser(user.uid);
          if(user.role === UserRole.STUDENT) {
             const freshStudents = getStoredStudents();
             const s = freshStudents.find(s => s.schoolID === user.schoolID);
             if (s) removeStudent(s.id);
          }
          refreshData();
      }
  };

  const handleDeleteStudentRecord = (student: StudentRecord) => {
      if(window.confirm(`Delete student ${student.name}?`)) {
          removeStudent(student.id);
          const freshUsers = getStoredUsers();
          const u = freshUsers.find(user => user.schoolID === student.schoolID);
          if (u) removeUser(u.uid);
          refreshData();
      }
  }

  const handleDeleteAnnouncement = (id: string) => {
      if(window.confirm('Delete this announcement globally?')) {
          deleteAnnouncement(id);
          refreshData();
      }
  }

  const handleDeleteFromModal = (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();

      if (modalType === 'student' && editingStudent) {
         if(window.confirm(`Delete student ${editingStudent.name}?`)) {
             removeStudent(editingStudent.id);
             const freshUsers = getStoredUsers();
             const u = freshUsers.find(u => u.schoolID === editingStudent.schoolID);
             if (u) removeUser(u.uid);
             refreshData();
             setShowAddModal(false);
         }
      } else if (editingUser) {
          if(window.confirm(`Delete user ${editingUser.name}?`)) {
              removeUser(editingUser.uid);
              if(editingUser.role === UserRole.STUDENT) {
                  const freshStudents = getStoredStudents();
                  const s = freshStudents.find(s => s.schoolID === editingUser.schoolID);
                  if (s) removeStudent(s.id);
              }
              refreshData();
              setShowAddModal(false);
          }
      }
  };

  const principals = users.filter(u => u.role === UserRole.PRINCIPAL);
  const teachers = users.filter(u => u.role === UserRole.TEACHER);

  const allClasses = Array.from(new Set(students.map(s => s.className))).sort();
  const filteredStudents = selectedClass === 'All' ? students : students.filter(s => s.className === selectedClass);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Admin Console</h1>
          <p className="text-slate-500">Full System Control & Data Management</p>
        </div>
        <div className="flex flex-wrap gap-2 bg-white p-1 rounded-lg border border-slate-200 shadow-sm">
            <button onClick={() => setActiveTab('overview')} className={`px-4 py-2 rounded-md text-sm font-medium ${activeTab === 'overview' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}>Overview</button>
            <button onClick={() => setActiveTab('schools')} className={`px-4 py-2 rounded-md text-sm font-medium flex gap-1 ${activeTab === 'schools' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}><School size={16} /> Schools</button>
            <button onClick={() => setActiveTab('principals')} className={`px-4 py-2 rounded-md text-sm font-medium ${activeTab === 'principals' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}>Principals</button>
            <button onClick={() => setActiveTab('teachers')} className={`px-4 py-2 rounded-md text-sm font-medium ${activeTab === 'teachers' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}>Teachers</button>
            <button onClick={() => setActiveTab('students')} className={`px-4 py-2 rounded-md text-sm font-medium ${activeTab === 'students' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}>Students</button>
            <button onClick={() => setActiveTab('announcements')} className={`px-4 py-2 rounded-md text-sm font-medium flex gap-1 ${activeTab === 'announcements' ? 'bg-slate-800 text-white' : 'text-slate-600'}`}><Megaphone size={16} /> Posts</button>
        </div>
      </header>

      {/* OVERVIEW TAB */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-indigo-100 w-fit rounded-lg mb-4"><School className="text-indigo-600" /></div>
            <h3 className="text-slate-500 text-sm font-medium">Schools</h3>
            <p className="text-3xl font-bold text-slate-800">{schools.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-blue-100 w-fit rounded-lg mb-4"><Building2 className="text-blue-600" /></div>
            <h3 className="text-slate-500 text-sm font-medium">Principals</h3>
            <p className="text-3xl font-bold text-slate-800">{principals.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
