    setFormGrade('');
    setFormSection('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
    setFormSchool('');

    setFormDob('');
    setFormAge('');
    setFormGender('Male');
    setFormFatherContact('');
    setFormMotherContact('');
  };

  const handleSaveSchool = (e: React.FormEvent) => {
