                                </td>
                                <td className="px-6 py-4 text-right">
                                    <button onClick={() => openSchoolModal(s)} className="text-blue-500 mr-3 hover:bg-blue-50 p-2 rounded"><Pencil size={18} /></button>
                                    <button onClick={() => handleDeleteSchool(s.id, s.name)} className="text-red-500 hover:bg-red-50 p-2 rounded"><Trash2 size={18} /></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
          </div>
      )}

      {/* PRINCIPALS TAB */}
      {activeTab === 'principals' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
