            <button onClick={() => openPrincipalModal()} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg"><Plus size={18} /> Add Principal</button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">Name</th><th className="px-6 py-4">School</th><th className="px-6 py-4">ID</th><th className="px-6 py-4">Pass</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
            <tbody className="divide-y divide-slate-100">
              {principals.map(p => (
                <tr key={p.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 flex gap-3"><img src={p.avatarUrl} className="w-8 h-8 rounded-full" /> {p.name}</td>
                  <td className="px-6 py-4 text-blue-700 font-semibold">{p.schoolName || 'Unassigned'}</td>
                  <td className="px-6 py-4 text-slate-600">{p.schoolID}</td>
