                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openPrincipalModal(p)} className="text-blue-500 mr-3"><Pencil size={18} /></button>
                    <button onClick={() => handleDeleteUser(p)} className="text-red-500"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* TEACHERS TAB */}
      {activeTab === 'teachers' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Teachers</h2>
            <button onClick={() => openTeacherModal()} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg"><Plus size={18} /> Add Teacher</button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">Name</th><th className="px-6 py-4">School</th><th className="px-6 py-4">ID</th><th className="px-6 py-4">Subject</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
            <tbody className="divide-y divide-slate-100">
              {teachers.map(t => (
                <tr key={t.uid} className="hover:bg-slate-50">
                  <td className="px-6 py-4 flex gap-3"><img src={t.avatarUrl} className="w-8 h-8 rounded-full" /> {t.name}</td>
                  <td className="px-6 py-4 text-blue-700 font-semibold">{t.schoolName || 'Unassigned'}</td>
                  <td className="px-6 py-4 text-slate-600">{t.schoolID}</td>
                  <td className="px-6 py-4 text-slate-600">{t.assignedSubject}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openTeacherModal(t)} className="text-blue-500 mr-3"><Pencil size={18} /></button>
                    <button onClick={() => handleDeleteUser(t)} className="text-red-500"><Trash2 size={18} /></button>
                  </td>
                </tr>
