                                        {s.config?.houseNames.map((h, i) => (
                                            <span key={i} className="px-2 py-0.5 bg-slate-100 rounded border border-slate-200 text-xs">{h}</span>
                                        )) || <span className="text-slate-400 italic">Default</span>}
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <button onClick={() => openSchoolModal(s)} className="text-blue-500 mr-3 hover:bg-blue-50 p-2 rounded"><Pencil size={18} /></button>
                                    <button onClick={() => handleDeleteSchool(s.id, s.name)} className="text-red-500 hover:bg-red-50 p-2 rounded"><Trash2 size={18} /></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
          </div>
      )}

      {/* PRINCIPALS TAB */}
      {activeTab === 'principals' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
            <h2 className="text-lg font-bold text-slate-800">Principals</h2>
            <button onClick={() => openPrincipalModal()} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg"><Plus size={18} /> Add Principal</button>
          </div>
          <table className="w-full text-left">
            <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">Name</th><th className="px-6 py-4">School</th><th className="px-6 py-4">ID</th><th className="px-6 py-4">Pass</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
            <tbody className="divide-y divide-slate-100">
              {principals.map(p => (
