                        </div>
                        <div className="w-24">
                          <label className="block text-xs font-bold text-slate-500 mb-1">Finals</label>
                          <input type="number" className="w-full px-3 py-2 border rounded-md text-sm" value={newFinal} onChange={e => setNewFinal(e.target.value)} />
                        </div>
                        <button onClick={handleAddMark} className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium h-[38px] hover:bg-blue-700">
                          <Plus size={16} /> Add
                        </button>
                    </div>
                    <table className="w-full text-left border border-slate-200 rounded-lg overflow-hidden">
                        <thead className="bg-slate-100 text-slate-600 text-xs uppercase">
                          <tr>
                            <th className="px-4 py-3">Subject</th>
                            <th className="px-4 py-3">Mid</th>
                            <th className="px-4 py-3">Final</th>
                            <th className="px-4 py-3">Avg</th>
                            <th className="px-4 py-3 text-right"></th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          {marksList.length === 0 && <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-400">No marks recorded.</td></tr>}
                          {marksList.map((m, idx) => (
                            <tr key={idx}>
                              <td className="px-4 py-3 font-medium">{m.subject}</td>
                              <td className="px-4 py-3 text-slate-600">{m.midTerm}</td>
                              <td className="px-4 py-3 text-slate-600">{m.final}</td>
                              <td className="px-4 py-3 font-bold text-blue-600">{((m.midTerm + m.final) / 2).toFixed(1)}</td>
                              <td className="px-4 py-3 text-right">
                                <button onClick={() => handleRemoveMark(idx)} className="text-red-500 hover:text-red-700">
                                  <Trash2 size={16} />
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                    </table>
                </div>
                <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100">
                  <button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 rounded-lg hover:bg-slate-50">Cancel</button>
                  <button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700">Save Grades</button>
                </div>
            </div>
          </div>
      )}

      {/* MODAL: ADMIN ATTENDANCE MANAGEMENT */}
      {showAttendanceModal && currentAttendanceStudent && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
              <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h2 className="text-xl font-bold text-slate-800">Manage Attendance</h2>
                      <p className="text-slate-500 text-sm">Student: {currentAttendanceStudent.name}</p>
                    </div>
                    <button onClick={() => setShowAttendanceModal(false)} className="text-slate-400 text-2xl hover:text-slate-600">&times;</button>
                  </div>

                  {/* Summary Stats */}
                  <div className="grid grid-cols-3 gap-4 mb-6">
                      <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Total Days</div>
                          <div className="text-xl font-bold text-slate-700">{getAttendanceStats(currentAttendanceStudent).totalWorking}</div>
                      </div>
                      <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Present</div>
                          <div className="text-xl font-bold text-green-600">{getAttendanceStats(currentAttendanceStudent).totalPresent}</div>
                      </div>
                       <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Percentage</div>
                          <div className="text-xl font-bold text-blue-600">{getAttendanceStats(currentAttendanceStudent).percentage}%</div>
                      </div>
                  </div>

                  {/* Edit Controls */}
                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                      <label className="block text-sm font-bold text-slate-600 mb-2">Select Date to Modify</label>
