                          <input className="w-full p-2 border rounded" value={scFormName} onChange={e => setScFormName(e.target.value)} required />
                      </div>
                      <div>
                          <label className="block text-sm font-medium mb-1">Maximum Grading Marks (Global)</label>
                          <input type="number" className="w-full p-2 border rounded" value={scFormMaxMarks} onChange={e => setScFormMaxMarks(e.target.value)} required />
