                    <input className="w-full p-2 border rounded" value={formName} onChange={e => setFormName(e.target.value)} required />
                </div>
                <div>
                    <label className="block text-sm font-medium mb-1">Assigned School</label>
                    <select className="w-full p-2 border rounded" value={formSchool} onChange={e => setFormSchool(e.target.value)} required>
                        <option value="">Select School</option>
                        {schools.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                    </select>
                </div>

                {/* Teacher/Student: Class & Section */}
                {(modalType === 'teacher' || modalType === 'student') && (
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Grade {modalType === 'teacher' && '(Optional)'}</label>
                            <select className="w-full p-2 border rounded" value={formGrade} onChange={e => { setFormGrade(e.target.value); setFormSection(''); }}>
                                <option value="">Select</option>
                                {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Section / Stream</label>
                            <select className="w-full p-2 border rounded" value={formSection} onChange={e => setFormSection(e.target.value)} disabled={!formGrade}>
                                <option value="">Select</option>
                                {getSectionOptions(formGrade).map(s => <option key={s} value={s}>{s}</option>)}
