                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Designation</label>
                            <input className="w-full p-2 border rounded" placeholder="Designation" value={formDesignation} onChange={e => setFormDesignation(e.target.value)} />
                        </div>
                    </div>
                    <div>
                         <label className="block text-sm font-medium mb-1">Subject</label>
                         <input className="w-full p-2 border rounded" placeholder="Subject" value={formSubject} onChange={e => setFormSubject(e.target.value)} />
                    </div>
                    {/* HOUSE SELECT */}
                    <div>
                         <label className="block text-sm font-medium mb-1">House Team</label>
                         <select className="w-full p-2 border rounded" value={formHouse} onChange={e => setFormHouse(e.target.value as HouseTeam)}>
                             <option value="">Select House</option>
                             {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                         </select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Email</label>
                            <input className="w-full p-2 border rounded" placeholder="Email" value={formEmail} onChange={e => setFormEmail(e.target.value)} />
                        </div>
                        <div>
                             <label className="block text-sm font-medium mb-1">Phone</label>
                             <input className="w-full p-2 border rounded" placeholder="Phone" value={formContact} onChange={e => setFormContact(e.target.value)} />
                        </div>
                    </div>
                    </>
                )}

                {/* Student Extras */}
                {modalType === 'student' && (
                    <>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Gender</label>
                            <select className="w-full p-2 border rounded" value={formGender} onChange={e => setFormGender(e.target.value)}>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Date of Birth</label>
                            <input className="w-full p-2 border rounded" type="date" value={formDob} onChange={handleDobChange} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Father Contact</label>
                            <input className="w-full p-2 border rounded" value={formFatherContact} onChange={e => setFormFatherContact(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Mother Contact</label>
                            <input className="w-full p-2 border rounded" value={formMotherContact} onChange={e => setFormMotherContact(e.target.value)} />
                        </div>
                    </div>
                     {/* HOUSE SELECT */}
                    <div>
                         <label className="block text-sm font-medium mb-1">House Team</label>
                         <select className="w-full p-2 border rounded" value={formHouse} onChange={e => setFormHouse(e.target.value as HouseTeam)}>
                             <option value="">Select House</option>
                             {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                         </select>
                    </div>
                    </>
                )}

                <div>
                    <label className="block text-sm font-medium mb-1">School ID</label>
                    <input className="w-full p-2 border rounded" value={formID} onChange={e => setFormID(e.target.value)} required />
                </div>
                <div>
                    <label className="block text-sm font-medium mb-1">Password</label>
                    <input className="w-full p-2 border rounded" value={formPassword} onChange={e => setFormPassword(e.target.value)} required />
                </div>

                <div className="flex gap-2 mt-4">
                    {(editingUser || editingStudent) && (
                        <button type="button" onClick={handleDeleteFromModal} className="px-4 py-2 text-red-600 border border-red-200 rounded hover:bg-red-50">Delete</button>
                    )}
                    <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 border rounded">Cancel</button>
                    <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded">Save</button>
                </div>
            </form>
          </div>
        </div>
      )}

      {/* ANNOUNCEMENT MODAL */}
      {showAnnModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
              <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
                  <h2 className="text-xl font-bold mb-4">Post Announcement</h2>
                  <form onSubmit={handlePostAnnouncement} className="space-y-4">
                      <div><label className="block text-sm font-medium">Title</label><input className="w-full p-2 border rounded" value={annTitle} onChange={e => setAnnTitle(e.target.value)} required /></div>
                      <div>
                          <label className="block text-sm font-medium">Target School</label>
                          <select className="w-full p-2 border rounded" value={annSchool} onChange={e => setAnnSchool(e.target.value)}>
                              <option value="">All Schools</option>
                              {schools.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                          </select>
                      </div>
                      <div>
                          <label className="block text-sm font-medium">Audience</label>
                          <select className="w-full p-2 border rounded" value={annAudience} onChange={(e: any) => setAnnAudience(e.target.value)}>
                              <option value="all">Everyone</option>
                              <option value="student">Students</option>
                              <option value="teacher">Teachers</option>
                          </select>
                      </div>
                      <div><label className="block text-sm font-medium">Content</label><textarea className="w-full p-2 border rounded h-32" value={annContent} onChange={e => setAnnContent(e.target.value)} required /></div>
                      <div className="flex gap-2"><button type="button" onClick={() => setShowAnnModal(false)} className="flex-1 p-2 border rounded">Cancel</button><button type="submit" className="flex-1 p-2 bg-blue-600 text-white rounded">Post</button></div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Users, 
  BookOpen, 
  Settings, 
  LogOut, 
  GraduationCap,
  ShieldAlert,
  Megaphone,
  ClipboardList
} from 'lucide-react';

interface SidebarProps {
  user: User;
  onLogout: () => void;
  currentPage: string;
  onNavigate: (page: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ user, onLogout, currentPage, onNavigate }) => {

  const getMenuItems = () => {
    const common = [
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { id: 'profile', label: 'My Profile', icon: Users },
    ];

    if (user.role === UserRole.PRINCIPAL) {
      return [
        ...common,
        { id: 'academics', label: 'Academics', icon: BookOpen },
        { id: 'announcements', label: 'Announcements', icon: Megaphone },
        { id: 'settings', label: 'School Settings', icon: Settings },
      ];
    }

    if (user.role === UserRole.TEACHER) {
      // Logic for Subject Teachers (No assigned class)
      // They only get Assignments, Announcements, Profile, Dashboard
      if (!user.assignedClass) {
        return [
           { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
           { id: 'assignments', label: 'Assignments', icon: ClipboardList },
           { id: 'announcements', label: 'News & Events', icon: Megaphone },
           { id: 'profile', label: 'My Profile', icon: Users },
        ]
      }

      return [
        ...common,
        { id: 'classes', label: 'My Classes', icon: BookOpen },
        { id: 'grades', label: 'Student Grades', icon: GraduationCap },
        { id: 'assignments', label: 'Assignments', icon: ClipboardList },
        { id: 'announcements', label: 'News & Events', icon: Megaphone },
      ];
    }

    if (user.role === UserRole.STUDENT) {
      return [
        ...common,
        { id: 'grades', label: 'My Grades', icon: GraduationCap },
        { id: 'assignments', label: 'Assignments', icon: ClipboardList },
        { id: 'teachers', label: 'My Teachers', icon: BookOpen },
        { id: 'announcements', label: 'News & Events', icon: Megaphone },
      ];
    }

    if (user.role === UserRole.SUPREME_ADMIN) {
      return [
        { id: 'dashboard', label: 'System Overview', icon: ShieldAlert },
        { id: 'schools', label: 'Schools', icon: BookOpen },
        { id: 'principals', label: 'Principals', icon: Users },
        { id: 'teachers', label: 'Teachers', icon: Users },
        { id: 'students', label: 'Students', icon: GraduationCap },
        { id: 'announcements', label: 'Announcements', icon: Megaphone },
        { id: 'assignments', label: 'Assignments', icon: ClipboardList },
      ];
    }

    return common;
  };

  const menuItems = getMenuItems();

  return (
    <div className="h-screen w-64 bg-slate-900 text-white flex flex-col fixed left-0 top-0 shadow-xl z-50 transition-all">
      <div className="p-6 border-b border-slate-700">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl shadow-lg">
            N
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight">NEXUS ERP</h1>
            <p className="text-xs text-slate-400">School Management</p>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const active = currentPage === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
                active 
                  ? 'bg-blue-600 text-white shadow-md' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <Icon size={20} />
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-700 bg-slate-900">
        <div className="flex items-center gap-3 mb-4 px-2">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-8 h-8 rounded-full bg-slate-700 object-cover"
          />
          <div className="overflow-hidden">
            <p className="text-sm font-medium truncate">{user.name}</p>
            <p className="text-xs text-slate-400 truncate capitalize">{user.role}</p>
          </div>
        </div>
        <button
          onClick={onLogout}
          className="w-full flex items-center gap-2 px-4 py-2 text-red-400 hover:bg-red-900/20 hover:text-red-300 rounded-lg transition-colors text-sm"
        >
          <LogOut size={16} />
          <span>Sign Out</span>
        </button>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { User, StudentRecord, MarkEntry, Announcement, HouseTeam, UserRole, Assignment } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash, Megaphone, Calendar, Shield, Flag, Globe, School, ClipboardList } from 'lucide-react';
import { getStoredStudents, getStoredAnnouncements, getStoredUsers, getStoredAssignments } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [assignments, setAssignments] = useState<Assignment[]>([]);

  useEffect(() => {
     // Fetch Announcements
     const allAnn = getStoredAnnouncements();
     const relevantAnn = allAnn.filter(a => 
         // Audience Filter
         (a.audience === 'all' || a.audience === 'student') &&
         // School Filter: Global (no schoolName) OR Matches User's School
         (!a.schoolName || a.schoolName === user.schoolName)
     );
     setAnnouncements(relevantAnn);

     // Fetch Assignments
     if (user.className && user.schoolName) {
         const allAssign = getStoredAssignments();
         const relevantAssign = allAssign.filter(a => {
             // Must match school
             if (a.schoolName !== user.schoolName) return false;

             // Handle Target Class Logic
             const [aGrade, aSection] = a.targetClass.split('-');
             const [uGrade, uSection] = (user.className || '').split('-');

             // Match Grade AND (Match Section OR Assignment is for All Sections)
             return aGrade === uGrade && (aSection === 'All' || aSection === uSection);
         });
         setAssignments(relevantAssign);
     }

  }, [user]);

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

   const getHouseColor = (house?: HouseTeam) => {
    if (!house) return 'text-slate-600 bg-slate-50';

    if (house.includes('Green')) return 'text-green-600 bg-green-50 border-green-200';
    if (house.includes('Blue')) return 'text-blue-600 bg-blue-50 border-blue-200';
    if (house.includes('Yellow')) return 'text-yellow-600 bg-yellow-50 border-yellow-200';
    if (house.includes('Red')) return 'text-red-600 bg-red-50 border-red-200';

    return 'text-indigo-600 bg-indigo-50 border-indigo-200';
  };

  if (currentPage === 'teachers') {
      const studentProfile = getStudentProfile();
      const allUsers = getStoredUsers();

      // Filter teachers: Must match Role, School, and Class.
      const myTeachers = allUsers.filter(u => 
          u.role === UserRole.TEACHER && 
          u.schoolName === user.schoolName && // Ensure same school
          (u.assignedClass === studentProfile?.className)
      );

      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Teachers</h1>
                 <p className="text-slate-500">Faculty directory for Class {studentProfile?.className || 'N/A'} at {user.schoolName}</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {myTeachers.length === 0 ? (
                      <div className="col-span-full p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                           <UserIcon size={48} className="mx-auto mb-4 opacity-20" />
                           <p>No specific class teachers found for your school.</p>
                      </div>
                  ) : (
                      myTeachers.map(teacher => (
                          <div key={teacher.uid} className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden hover:shadow-md transition-shadow">
                              <div className="p-6 flex flex-col items-center text-center border-b border-slate-50">
                                  <img 
                                      src={teacher.avatarUrl} 
                                      alt={teacher.name} 
                                      className="w-20 h-20 rounded-full bg-slate-100 object-cover mb-4 border-4 border-white shadow-sm"
                                  />
                                  <h3 className="font-bold text-lg text-slate-800">{teacher.name}</h3>
                                  <p className="text-blue-600 font-medium text-sm">{teacher.assignedSubject || 'Teacher'}</p>
                                  <p className="text-slate-400 text-xs mt-1">{teacher.designation}</p>
                              </div>
                              <div className="p-4 bg-slate-50 space-y-3">
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Mail size={16} />
                                      </div>
                                      <div className="overflow-hidden">
                                          <p className="text-xs text-slate-500 font-bold uppercase">Email</p>
                                          <p className="text-slate-700 truncate" title={teacher.email || 'N/A'}>
                                              {teacher.email || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white rounded-lg text-slate-400 shadow-sm">
                                          <Phone size={16} />
                                      </div>
                                      <div>
                                          <p className="text-xs text-slate-500 font-bold uppercase">Contact</p>
                                          <p className="text-slate-700">
                                              {teacher.contactNumber || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'profile') {
    const studentProfile = getStudentProfile();

    if (!studentProfile) {
        return (
            <div className="p-8 text-center bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="text-slate-400 mb-2">
                    <UserIcon size={48} className="mx-auto opacity-50" />
                </div>
                <h3 className="text-lg font-bold text-slate-700">Profile Not Found</h3>
                <p className="text-slate-500">
                    Detailed information is not available. Please ask your class teacher to update your student record.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
             <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                {/* Header Section */}
                <div className="bg-slate-50 p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 font-mono text-sm">
                            <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-slate-700 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
                            </span>
                            {studentProfile.studentPost && (
                                <span className="px-3 py-1 bg-purple-100 border border-purple-200 rounded-full text-purple-700 flex items-center gap-1 font-semibold">
                                    <Shield size={14} /> {studentProfile.studentPost}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {/* Details Grid */}
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">

                    {/* Academic Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Academic Information</h3>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Class</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.className}</p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Roll Number</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.rollNumber}</p>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">House Team</label>
                                <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(studentProfile.house)}`}>
                                    <Flag size={18} />
                                    {studentProfile.house || 'No House Assigned'}
                                </div>
                            </div>
                            {user.schoolName && (
                                <div className="col-span-2">
                                    <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School</label>
                                    <p className="text-lg font-medium text-slate-800">{user.schoolName}</p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age & Gender</label>
                                <p className="text-lg font-medium text-slate-800">
                                    {studentProfile.age ? `${studentProfile.age} Years Old` : <span className="text-slate-400 italic">Not set</span>}
                                    <span className="mx-2 text-slate-300">|</span>
                                    {studentProfile.gender || 'Not set'}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Date of Birth</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Calendar size={18} className="text-slate-400" />
                                    {studentProfile.dob ? new Date(studentProfile.dob).toLocaleDateString(undefined, {
                                        year: 'numeric',
                                        month: 'long',
                                        day: 'numeric'
                                    }) : <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-purple-100 text-purple-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Mother's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.motherContact || 'N/A'}</p>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">Latest updates from the school administration.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <div className="flex items-center gap-2 mt-1">
                                        <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                        {!ann.schoolName && (
                                            <span className="flex items-center gap-1 text-[10px] uppercase font-bold px-2 py-0.5 bg-purple-50 text-purple-600 rounded-full border border-purple-100">
                                                <Globe size={10} /> Global
                                            </span>
                                        )}
                                        {ann.schoolName && (
                                            <span className="flex items-center gap-1 text-[10px] uppercase font-bold px-2 py-0.5 bg-blue-50 text-blue-600 rounded-full border border-blue-100">
                                                <School size={10} /> {ann.schoolName}
                                            </span>
                                        )}
                                     </div>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'assignments') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                  <h1 className="text-2xl font-bold text-slate-800">My Assignments</h1>
                  <p className="text-slate-500">Tasks and homework for your class.</p>
              </header>

              <div className="grid grid-cols-1 gap-6">
                  {assignments.length === 0 ? (
                      <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                          <ClipboardList size={48} className="mx-auto mb-4 opacity-20" />
                          <p>No assignments found for your class at this time.</p>
                      </div>
                  ) : (
                      assignments.map(assign => (
                          <div key={assign.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-purple-500">
                              <div className="flex justify-between items-start mb-3">
                                  <div>
                                      <h3 className="font-bold text-lg text-slate-800">{assign.title}</h3>
                                      <div className="flex flex-wrap items-center gap-2 mt-2">
                                          <span className="text-xs font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded border border-purple-100">{assign.subject}</span>
                                          <span className="text-xs text-slate-500 flex items-center gap-1"><UserIcon size={12}/> {assign.authorName}</span>
                                          <span className="text-xs text-red-500 font-medium flex items-center gap-1"><Clock size={12}/> Due: {assign.dueDate}</span>
                                      </div>
                                  </div>
                              </div>
                              <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{assign.content}</p>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
    const studentProfile = getStudentProfile();
    const marks = studentProfile?.marks || [];

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-slate-800">Academic Transcript</h1>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Subject</th>
                            <th className="px-6 py-4">Mid-Term</th>
                            <th className="px-6 py-4">Finals</th>
                            <th className="px-6 py-4">Avg Score</th>
                            <th className="px-6 py-4">Grade</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {marks.length === 0 ? (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400">No grades available yet.</td></tr>
                        ) : (
                            marks.map((m, i) => {
                                const avg = (m.midTerm + m.final) / 2;
                                return (
                                    <tr key={i}>
                                        <td className="px-6 py-4 font-medium">{m.subject}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.midTerm}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.final}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800">{avg.toFixed(1)}</td>
                                        <td className={`px-6 py-4 font-bold ${avg >= 70 ? 'text-green-600' : 'text-red-500'}`}>
                                            {calculateGrade(avg)}
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {studentProfile && studentProfile.gradeAverage > 0 && (
                <div className="p-4 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-700 flex justify-between items-center">
                    <span>Cumulative Grade Average</span>
                    <span className="font-bold text-lg">{studentProfile.gradeAverage}%</span>
                </div>
            )}
        </div>
    )
  }

  return (
    <div className="space-y-6">
      <header className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex items-center gap-6">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-20 h-20 rounded-full border-4 border-white/30 bg-slate-700"
          />
          <div>
            <h1 className="text-3xl font-bold mb-1">Hello, {user.name}</h1>
            <p className="text-blue-100 font-mono opacity-80">{user.schoolID} • Class {user.className || 'N/A'}</p>
            {user.schoolName && <p className="text-xs bg-white/20 inline-block px-2 py-1 rounded mt-2">{user.schoolName}</p>}
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Recent Grades */}
