          authorName: selectedTeacher.name,
          teacherUid: selectedTeacher.uid,
          createdAt: new Date().toISOString()
      };

      if (editingAssignment) {
          updateAssignment(assignmentData);
      } else {
          addAssignment(assignmentData);
      }
      refreshData();
      setShowAssignModal(false);
  };

  const handleDeleteAssignment = (id: string) => {
      if (window.confirm('Delete this assignment permanently?')) {
          deleteAssignment(id);
          refreshData();
      }
  };

  const resetForm = () => {
    setEditingUser(null);
    setEditingStudent(null);
    setFormError('');
    setFormName('');
    setFormID('');
    setFormPassword('');
    setFormGrade('');
    setFormSection('');
    setFormSubject('');
    setFormDesignation('');
    setFormHouse('');
    setFormPost('');
    setFormEmail('');
    setFormContact('');
    setFormSchool('');

    setFormDob('');
    setFormAge('');
    setFormGender('Male');
    setFormFatherContact('');
    setFormMotherContact('');
  };

  const handleSaveSchool = (e: React.FormEvent) => {
      e.preventDefault();
      const config: SchoolConfig = {
          maxMarks: parseInt(scFormMaxMarks) || 100,
          houseNames: scFormHouses.split(',').map(s => s.trim()).filter(s => s),
