                 </div>
                 <button onClick={() => openSchoolModal()} className="px-6 py-2 bg-indigo-600 text-white rounded-lg flex gap-2 items-center hover:bg-indigo-700 transition-colors"><Plus size={18} /> Add New School</button>
             </div>

