                <table className="w-full text-left">
                    <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">School Name</th><th className="px-6 py-4">Max Marks</th><th className="px-6 py-4">Houses Config</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
                    <tbody className="divide-y divide-slate-100">
                        {schools.map(s => (
                            <tr key={s.id} className="hover:bg-slate-50">
                                <td className="px-6 py-4 font-medium">
                                    {s.name}
                                    <div className="text-xs text-slate-400 font-mono mt-1">{s.id}</div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">{s.config?.maxMarks || 100}</td>
                                <td className="px-6 py-4 text-slate-600 text-sm">
                                    <div className="flex gap-1 flex-wrap">
                                        {s.config?.houseNames.map((h, i) => (
                                            <span key={i} className="px-2 py-0.5 bg-slate-100 rounded border border-slate-200 text-xs">{h}</span>
                                        )) || <span className="text-slate-400 italic">Default</span>}
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <button onClick={() => openSchoolModal(s)} className="text-blue-500 mr-3 hover:bg-blue-50 p-2 rounded"><Pencil size={18} /></button>
                                    <button onClick={() => handleDeleteSchool(s.id, s.name)} className="text-red-500 hover:bg-red-50 p-2 rounded"><Trash2 size={18} /></button>
                                </td>
