                            <td className="px-6 py-4 font-medium">{s.name}</td>
                            <td className="px-6 py-4 text-blue-700">{s.schoolName || 'Unassigned'}</td>
                            <td className="px-6 py-4">{s.className}</td>
                            <td className="px-6 py-4 text-slate-500">{s.schoolID}</td>
                            <td className="px-6 py-4 text-center">
                              <div className="flex justify-center gap-2">
                                <button onClick={() => openMarksModal(s)} className="p-2 bg-slate-50 hover:bg-slate-100 text-slate-600 rounded border border-slate-200" title="Edit Marks">
                                  <GraduationCap size={16} />
                                </button>
                                <button onClick={() => openAttendanceModal(s)} className="p-2 bg-slate-50 hover:bg-slate-100 text-slate-600 rounded border border-slate-200" title="Attendance">
                                  <Calendar size={16} />
                                </button>
                              </div>
                            </td>
                            <td className="px-6 py-4 text-right">
                                <button onClick={() => openStudentModal(s)} className="text-blue-500 mr-3"><Pencil size={18} /></button>
                                <button onClick={() => handleDeleteStudentRecord(s)} className="text-red-500"><Trash2 size={18} /></button>
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>
        </div>
      )}

      {/* ANNOUNCEMENTS TAB */}
      {activeTab === 'announcements' && (
          <div className="space-y-6">
              <div className="flex justify-between items-center">
                  <h2 className="text-xl font-bold text-slate-800">Announcements</h2>
                  <button onClick={openAnnouncementModal} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg"><Plus size={18} /> Create Post</button>
              </div>
              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                  <table className="w-full text-left">
                      <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">Title</th><th className="px-6 py-4">School</th><th className="px-6 py-4">Audience</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
                      <tbody className="divide-y divide-slate-100">
                          {announcements.map(ann => (
                              <tr key={ann.id} className="hover:bg-slate-50">
                                  <td className="px-6 py-4 font-medium">{ann.title}</td>
                                  <td className="px-6 py-4">{ann.schoolName || 'Global'}</td>
                                  <td className="px-6 py-4 capitalize">{ann.audience}</td>
                                  <td className="px-6 py-4 text-right"><button onClick={() => handleDeleteAnnouncement(ann.id)} className="text-red-500"><Trash2 size={18} /></button></td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      )}

      {/* ASSIGNMENTS TAB */}
      {activeTab === 'assignments' && (
          <div className="space-y-6">
              <div className="flex justify-between items-center">
                  <h2 className="text-xl font-bold text-slate-800">Assignments</h2>
                  <button onClick={() => openAssignModal()} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg"><Plus size={18} /> New Assignment</button>
              </div>
              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                  <table className="w-full text-left">
                      <thead className="bg-white text-slate-500 text-xs uppercase border-b border-slate-100"><tr><th className="px-6 py-4">Title</th><th className="px-6 py-4">School</th><th className="px-6 py-4">Class</th><th className="px-6 py-4">By</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
                      <tbody className="divide-y divide-slate-100">
                          {assignments.map(assign => (
                              <tr key={assign.id} className="hover:bg-slate-50">
                                  <td className="px-6 py-4 font-medium">{assign.title}</td>
                                  <td className="px-6 py-4 text-slate-600">{assign.schoolName}</td>
                                  <td className="px-6 py-4 text-slate-600">{assign.targetClass}</td>
                                  <td className="px-6 py-4 text-slate-600">{assign.authorName}</td>
                                  <td className="px-6 py-4 text-right">
                                      <button onClick={() => openAssignModal(assign)} className="text-blue-500 mr-3"><Pencil size={18} /></button>
                                      <button onClick={() => handleDeleteAssignment(assign.id)} className="text-red-500"><Trash2 size={18} /></button>
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      )}

      {/* MODAL: ADMIN MARKS MANAGEMENT */}
      {showMarksModal && currentMarksStudent && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
            <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl relative">
                <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                  <div>
                    <h2 className="text-xl font-bold text-slate-800">Manage Marks (Admin)</h2>
                    <p className="text-slate-500 text-sm">Student: {currentMarksStudent.name} ({currentMarksStudent.schoolName})</p>
                  </div>
                  <button onClick={() => setShowMarksModal(false)} className="text-slate-400 text-2xl hover:text-slate-600">&times;</button>
                </div>
                <div className="space-y-6">
                    <div className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg border border-slate-200">
                        <div className="flex-1">
                          <label className="block text-xs font-bold text-slate-500 mb-1">Subject</label>
                          <input className="w-full px-3 py-2 border rounded-md text-sm" value={newSubject} onChange={e => setNewSubject(e.target.value)} />
                        </div>
                        <div className="w-24">
                          <label className="block text-xs font-bold text-slate-500 mb-1">Mid-Term</label>
                          <input type="number" className="w-full px-3 py-2 border rounded-md text-sm" value={newMidTerm} onChange={e => setNewMidTerm(e.target.value)} />
                        </div>
                        <div className="w-24">
                          <label className="block text-xs font-bold text-slate-500 mb-1">Finals</label>
                          <input type="number" className="w-full px-3 py-2 border rounded-md text-sm" value={newFinal} onChange={e => setNewFinal(e.target.value)} />
                        </div>
                        <button onClick={handleAddMark} className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium h-[38px] hover:bg-blue-700">
                          <Plus size={16} /> Add
                        </button>
                    </div>
                    <table className="w-full text-left border border-slate-200 rounded-lg overflow-hidden">
                        <thead className="bg-slate-100 text-slate-600 text-xs uppercase">
                          <tr>
                            <th className="px-4 py-3">Subject</th>
                            <th className="px-4 py-3">Mid</th>
                            <th className="px-4 py-3">Final</th>
                            <th className="px-4 py-3">Avg</th>
                            <th className="px-4 py-3 text-right"></th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          {marksList.length === 0 && <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-400">No marks recorded.</td></tr>}
                          {marksList.map((m, idx) => (
                            <tr key={idx}>
                              <td className="px-4 py-3 font-medium">{m.subject}</td>
                              <td className="px-4 py-3 text-slate-600">{m.midTerm}</td>
                              <td className="px-4 py-3 text-slate-600">{m.final}</td>
                              <td className="px-4 py-3 font-bold text-blue-600">{((m.midTerm + m.final) / 2).toFixed(1)}</td>
                              <td className="px-4 py-3 text-right">
                                <button onClick={() => handleRemoveMark(idx)} className="text-red-500 hover:text-red-700">
                                  <Trash2 size={16} />
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                    </table>
                </div>
                <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100">
                  <button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 rounded-lg hover:bg-slate-50">Cancel</button>
                  <button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700">Save Grades</button>
                </div>
            </div>
          </div>
      )}

      {/* MODAL: ADMIN ATTENDANCE MANAGEMENT */}
      {showAttendanceModal && currentAttendanceStudent && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
              <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h2 className="text-xl font-bold text-slate-800">Manage Attendance</h2>
                      <p className="text-slate-500 text-sm">Student: {currentAttendanceStudent.name}</p>
                    </div>
                    <button onClick={() => setShowAttendanceModal(false)} className="text-slate-400 text-2xl hover:text-slate-600">&times;</button>
                  </div>

                  {/* Summary Stats */}
                  <div className="grid grid-cols-3 gap-4 mb-6">
                      <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Total Days</div>
                          <div className="text-xl font-bold text-slate-700">{getAttendanceStats(currentAttendanceStudent).totalWorking}</div>
                      </div>
                      <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Present</div>
                          <div className="text-xl font-bold text-green-600">{getAttendanceStats(currentAttendanceStudent).totalPresent}</div>
                      </div>
                       <div className="bg-slate-50 p-3 rounded-lg text-center border border-slate-100">
                          <div className="text-xs text-slate-400 uppercase font-bold">Percentage</div>
                          <div className="text-xl font-bold text-blue-600">{getAttendanceStats(currentAttendanceStudent).percentage}%</div>
                      </div>
                  </div>

                  {/* Edit Controls */}
                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                      <label className="block text-sm font-bold text-slate-600 mb-2">Select Date to Modify</label>
                      <input 
                          type="date" 
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-200 mb-4"
                          value={attendanceDate}
                          onChange={(e) => setAttendanceDate(e.target.value)}
                          max={new Date().toISOString().split('T')[0]} 
                      />

                      <div className="flex gap-3">
                          <button 
                              onClick={() => toggleAttendanceForDate(true)}
                              className={`flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2 border transition-colors ${
                                  currentAttendanceStudent.attendanceHistory?.[attendanceDate] === true
                                  ? 'bg-green-600 text-white border-green-700 shadow-sm'
                                  : 'bg-white text-slate-600 border-slate-200 hover:border-green-300'
                              }`}
                          >
                              <CheckCircle size={18} /> Present
                          </button>
                          <button 
                              onClick={() => toggleAttendanceForDate(false)}
                              className={`flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2 border transition-colors ${
                                  currentAttendanceStudent.attendanceHistory?.[attendanceDate] === false
                                  ? 'bg-red-600 text-white border-red-700 shadow-sm'
                                  : 'bg-white text-slate-600 border-slate-200 hover:border-red-300'
                              }`}
                          >
                              <XCircle size={18} /> Absent
                          </button>
                      </div>
                      <p className="text-xs text-slate-400 mt-3 text-center">Changes are saved immediately.</p>
                  </div>

                  <div className="mt-6">
                      <button onClick={() => setShowAttendanceModal(false)} className="w-full py-2 bg-slate-100 text-slate-600 font-medium rounded-lg hover:bg-slate-200">Close</button>
                  </div>
              </div>
          </div>
      )}

      {/* USER MODAL (PRINCIPAL, TEACHER, STUDENT) */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
          <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
            <h2 className="text-xl font-bold mb-4">
                {editingUser || editingStudent ? 'Edit' : 'Add'} {modalType.charAt(0).toUpperCase() + modalType.slice(1)}
            </h2>
            <form onSubmit={handleSaveUser} className="space-y-4">
                {/* Global Form Error Display */}
                {formError && (
                    <div className="p-3 bg-red-50 border border-red-100 text-red-700 rounded-lg text-sm flex items-center gap-2">
                        <AlertTriangle size={16} /> {formError}
                    </div>
                )}

                <div>
                    <label className="block text-sm font-medium mb-1">Full Name</label>
                    <input className="w-full p-2 border rounded" value={formName} onChange={e => setFormName(e.target.value)} required />
                </div>
                <div>
                    <label className="block text-sm font-medium mb-1">Assigned School</label>
                    <select className="w-full p-2 border rounded" value={formSchool} onChange={e => setFormSchool(e.target.value)} required>
                        <option value="">Select School</option>
                        {schools.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                    </select>
                </div>

                {/* Teacher/Student: Class & Section */}
                {(modalType === 'teacher' || modalType === 'student') && (
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Grade {modalType === 'teacher' && '(Optional)'}</label>
                            <select className="w-full p-2 border rounded" value={formGrade} onChange={e => { setFormGrade(e.target.value); setFormSection(''); }}>
                                <option value="">Select</option>
                                {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Section / Stream</label>
                            <select className="w-full p-2 border rounded" value={formSection} onChange={e => setFormSection(e.target.value)} disabled={!formGrade}>
                                <option value="">Select</option>
                                {getSectionOptions(formGrade).map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>
                )}

                {/* Teacher Extras */}
                {modalType === 'teacher' && (
                    <>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Gender</label>
                            <select className="w-full p-2 border rounded" value={formGender} onChange={e => setFormGender(e.target.value)}>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Designation</label>
                            <input className="w-full p-2 border rounded" placeholder="Designation" value={formDesignation} onChange={e => setFormDesignation(e.target.value)} />
                        </div>
                    </div>
                    <div>
                         <label className="block text-sm font-medium mb-1">Subject</label>
                         <input className="w-full p-2 border rounded" placeholder="Subject" value={formSubject} onChange={e => setFormSubject(e.target.value)} />
                    </div>
                    {/* HOUSE SELECT */}
                    <div>
                         <label className="block text-sm font-medium mb-1">House Team</label>
                         <select className="w-full p-2 border rounded" value={formHouse} onChange={e => setFormHouse(e.target.value as HouseTeam)}>
                             <option value="">Select House</option>
                             {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                         </select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Email</label>
                            <input className="w-full p-2 border rounded" placeholder="Email" value={formEmail} onChange={e => setFormEmail(e.target.value)} />
                        </div>
                        <div>
                             <label className="block text-sm font-medium mb-1">Phone</label>
                             <input className="w-full p-2 border rounded" placeholder="Phone" value={formContact} onChange={e => setFormContact(e.target.value)} />
                        </div>
                    </div>
                    </>
                )}

                {/* Student Extras */}
                {modalType === 'student' && (
                    <>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Gender</label>
                            <select className="w-full p-2 border rounded" value={formGender} onChange={e => setFormGender(e.target.value)}>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Date of Birth</label>
                            <input className="w-full p-2 border rounded" type="date" value={formDob} onChange={handleDobChange} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Father Contact</label>
                            <input className="w-full p-2 border rounded" value={formFatherContact} onChange={e => setFormFatherContact(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Mother Contact</label>
                            <input className="w-full p-2 border rounded" value={formMotherContact} onChange={e => setFormMotherContact(e.target.value)} />
                        </div>
                    </div>
                     {/* HOUSE SELECT */}
                    <div>
                         <label className="block text-sm font-medium mb-1">House Team</label>
                         <select className="w-full p-2 border rounded" value={formHouse} onChange={e => setFormHouse(e.target.value as HouseTeam)}>
                             <option value="">Select House</option>
                             {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                         </select>
                    </div>
                    </>
                )}

                <div>
                    <label className="block text-sm font-medium mb-1">School ID</label>
                    <input className="w-full p-2 border rounded" value={formID} onChange={e => setFormID(e.target.value)} required />
                </div>
                <div>
                    <label className="block text-sm font-medium mb-1">Password</label>
                    <input className="w-full p-2 border rounded" value={formPassword} onChange={e => setFormPassword(e.target.value)} required />
                </div>

                <div className="flex gap-2 mt-4">
                    {(editingUser || editingStudent) && (
                        <button type="button" onClick={handleDeleteFromModal} className="px-4 py-2 text-red-600 border border-red-200 rounded hover:bg-red-50">Delete</button>
                    )}
                    <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 border rounded">Cancel</button>
                    <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded">Save</button>
                </div>
            </form>
          </div>
        </div>
      )}

      {/* ANNOUNCEMENT MODAL */}
      {showAnnModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
              <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
                  <h2 className="text-xl font-bold mb-4">Post Announcement</h2>
                  <form onSubmit={handlePostAnnouncement} className="space-y-4">
                      <div><label className="block text-sm font-medium">Title</label><input className="w-full p-2 border rounded" value={annTitle} onChange={e => setAnnTitle(e.target.value)} required /></div>
                      <div>
                          <label className="block text-sm font-medium">Target School</label>
                          <select className="w-full p-2 border rounded" value={annSchool} onChange={e => setAnnSchool(e.target.value)}>
                              <option value="">All Schools</option>
                              {schools.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                          </select>
                      </div>
                      <div>
                          <label className="block text-sm font-medium">Audience</label>
                          <select className="w-full p-2 border rounded" value={annAudience} onChange={(e: any) => setAnnAudience(e.target.value)}>
                              <option value="all">Everyone</option>
                              <option value="student">Students</option>
                              <option value="teacher">Teachers</option>
                          </select>
                      </div>
                      <div><label className="block text-sm font-medium">Content</label><textarea className="w-full p-2 border rounded h-32" value={annContent} onChange={e => setAnnContent(e.target.value)} required /></div>
                      <div className="flex gap-2"><button type="button" onClick={() => setShowAnnModal(false)} className="flex-1 p-2 border rounded">Cancel</button><button type="submit" className="flex-1 p-2 bg-blue-600 text-white rounded">Post</button></div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

export default AdminDashboard;
